const $=s=>document.querySelector(s), clamp=n=>Math.max(0,Math.min(100,n)), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,view='home',eventNow=null,toastTimer;
const app=$('#app'),dlg=$('#modal');
function emptyState(){return {name:'',surname:'',pronouns:'он',gender:'Мужской',year:2026,month:0,age:0,birthDay:1,birthMonth:0,country:COUNTRIES[0].name,city:'Волгоград',currency:'RUB',symbol:'₽',birthCountry:'Россия',language:'Русский',money:100000,health:62,mind:8,mood:72,energy:75,fatigue:0,relations:12,reputation:0,career:'Без карьеры',careerRank:'Не выбрана',jobLevel:0,school:'Школа',schoolGrade:3,education:'Школа',married:false,children:0,house:'Съёмная комната',car:'Нет машины',phone:'Простой телефон',clothes:'Повседневная одежда',pet:'Нет питомца',familyWealth:'Случайно',eventDifficulty:'Обычная',autosave:true,sound:false,dark:false,logs:[],achievements:[],statsHistory:[],album:[],goals:[],savedAt:null,exchangeRate:null,dead:false};}
function slots(){try{return JSON.parse(localStorage.getItem('lifeSlots')||'{}')}catch{return {}}}function persist(){if(state){localStorage.setItem('lifeActive',JSON.stringify(state));localStorage.setItem('lifeSlots',JSON.stringify({...slots(),[state.slot||'Жизнь 1']:state}));}}
function init(){try{state=JSON.parse(localStorage.getItem('lifeActive')||'null')}catch{} if(state?.name&&!state.dead)renderGame();else renderSetup()}
function log(text){state.logs.unshift({date:`${monthName()} ${state.age} лет`,text});state.logs=state.logs.slice(0,300)}function monthName(){return ['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'][state.month]}function fmt(n){return new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(Math.round(n))}function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
function renderSetup(){state=state?.name?state:emptyState();app.innerHTML=`<section class="setup-wrap"><span class="eyebrow">НОВАЯ ИСТОРИЯ · 01</span><h1>Чья жизнь начнётся?</h1><p class="subtitle">Создай персонажа, выбери или доверь случаю страну рождения, стартовые условия и характер. Потом решения будут менять его историю месяц за месяцем.</p><div class="form-grid"><label class="field">Имя<input id="name" maxlength="24" placeholder="Например, Алекс"></label><label class="field">Фамилия<input id="surname" maxlength="28" placeholder="Фамилия семьи"></label><label class="field">Пол<select id="gender"><option>Мужской</option><option>Женский</option><option>Другой</option></select></label><label class="field">Местоимения<select id="pronouns"><option>он</option><option>она</option><option>они</option><option>свои</option></select></label><label class="field">Страна рождения<select id="country"><option value="random">Случайная страна</option>${COUNTRIES.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></label><label class="field">Город рождения<select id="city"><option value="random">Случайный город</option></select></label><label class="field">Дата рождения<input id="birthDay" type="number" min="1" max="31" value="1"></label><label class="field">Месяц рождения<select id="birthMonth">${['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'].map((x,i)=>`<option value="${i}">${x}</option>`).join('')}</select></label><label class="field">Семья<select id="wealth"><option>Случайно</option><option>Скромный достаток</option><option>Обычный достаток</option><option>Обеспеченная семья</option></select></label><label class="field">Сложность событий<select id="difficulty"><option>Спокойная</option><option selected>Обычная</option><option>Непредсказуемая</option></select></label><label class="field">Характер<select id="personality"><option>Случайно</option><option>Любознательный</option><option>Смелый</option><option>Общительный</option><option>Терпеливый</option><option>Амбициозный</option></select></label><label class="field">Внешность<select id="looks"><option>Случайно</option><option>Настроить позже</option></select></label><label class="field">Язык интерфейса<select id="locale"><option value="ru">Русский</option></select><small>Определяется платформой; пока доступен русский язык.</small></label><label class="field">Валюта отображения<select id="displayCurrency"><option value="RUB">Рубли (₽)</option><option value="local">Валюта страны</option></select></label></div><div class="setup-footer"><button id="startGame" class="btn primary">Начать историю →</button><button id="loadSlot" class="btn ghost">Загрузить сохранение</button><span class="muted" style="font-size:12px">Сохранение останется в этом браузере.</span></div></section>`;
 const cs=$('#country'), city=$('#city');function fill(){let c=COUNTRIES.find(x=>x.name===cs.value);city.innerHTML='<option value="random">Случайный город</option>'+((c?.cities||[]).map(x=>`<option>${esc(x)}</option>`).join(''))}cs.addEventListener('change',fill);fill();$('#startGame').onclick=startGame;$('#loadSlot').onclick=()=>openSlots();}
function startGame(){let name=$('#name').value.trim();if(!name){toast('Сначала введи имя персонажа');$('#name').focus();return}let s=emptyState();let co=$('#country').value==='random'?COUNTRIES[Math.floor(Math.random()*COUNTRIES.length)]:COUNTRIES.find(c=>c.name===$('#country').value);s.name=name;s.surname=$('#surname').value.trim()||'Новый';s.gender=$('#gender').value;s.pronouns=$('#pronouns').value;s.birthCountry=co.name;s.country=co.name;s.city=$('#city').value==='random'?co.cities[Math.floor(Math.random()*co.cities.length)]:$('#city').value;s.currency=co.currency;s.symbol=$('#displayCurrency').value==='RUB'?'₽':co.symbol;s.language=co.lang;s.familyWealth=$('#wealth').value;s.eventDifficulty=$('#difficulty').value;s.personality=$('#personality').value==='Случайно'?['Любознательный','Смелый','Общительный','Терпеливый','Амбициозный'][Math.floor(Math.random()*5)]:$('#personality').value;s.slot=window.lifeNewSlotPending||'Жизнь 1';s.money=s.familyWealth==='Скромный достаток'?25000:s.familyWealth==='Обеспеченная семья'?300000:s.familyWealth==='Обычный достаток'?100000:Math.floor(25000+Math.random()*250000);s.age=0;s.month=0;s.year=2026;s.logs=[];log(`Родился в городе ${s.city}, ${co.name}. Семья: ${s.familyWealth.toLowerCase()}.`);persist();renderGame();openModal('РОДИЛСЯ / РОДИЛАСЬ','Свидетельство о рождении',`<div class="forecast">На свет появился <b>${esc(s.name)} ${esc(s.surname)}</b>, город ${esc(s.city)}, ${esc(s.country)}. Впереди целая жизнь — шаг за шагом.</div><div class="modal-actions"><button class="btn primary" data-close>Начать жизнь</button><button class="btn ghost" data-career>Выбрать будущую карьеру</button></div>`);}
function openModal(label,title,html){$('#modalEyebrow').textContent=label;$('#modalContent').innerHTML=`<h2 class="modal-title">${title}</h2>${html}`;dlg.showModal();$('#modalContent').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dlg.close());$('#modalContent').querySelectorAll('[data-career]').forEach(b=>{b.onclick=()=>{dlg.close();chooseCareer()}})}$('#closeModal').onclick=()=>dlg.close();
function metric(name,val,cls=''){return `<div class="metric ${cls}"><div class="metric-name"><span>${name}</span><span>${Math.round(val)}%</span></div><div class="metric-value">${Math.round(val)}<span class="muted" style="font-size:11px"> / 100</span></div><div class="meter"><span style="width:${clamp(val)}%"></span></div></div>`}
function renderGame(){if(!state)return;const m=state.money;app.innerHTML=`<section class="game-top"><div class="metric money"><div class="metric-name"><span>${esc(state.name)} ${esc(state.surname)}</span><span>${esc(state.symbol)}</span></div><div class="metric-value">${fmt(m)} ${esc(state.symbol)}</div><div class="muted" style="font-size:11px">${esc(state.city)}, ${esc(state.country)}</div></div>${metric('Здоровье',state.health)}${metric('Ум',state.mind)}${metric('Настроение',state.mood)}${metric('Энергия',state.energy)}${metric('Репутация',Math.min(100,state.reputation+50))}</section><div class="turnbar"><div class="turn-date">${state.age} лет, ${monthName()} <small>${state.career==='Без карьеры'?'Жизнь в развитии':esc(state.career+' · '+state.careerRank)}</small></div><button class="btn warm" id="nextMonth">Следующий месяц →</button><button class="btn ghost" id="toEvent">До события</button><button class="btn ghost" id="speed">⏩ 3 месяца</button><button class="btn ghost" id="pause">Ⅱ Пауза</button></div><div class="layout"><nav class="sidebar"><div class="nav-label">ЖИЗНЬ</div>${nav('home','⌂','Главная')}${nav('health','♡','Здоровье')}${nav('relations','♧','Отношения')}${nav('home','⌂','Дом') }<div class="nav-label">РАЗВИТИЕ</div>${nav('career','⚒','Учёба и карьера')}${nav('family','♙','Семья и альбом')}${nav('money','¤','Имущество и деньги')}<div class="nav-label">МИР</div>${nav('world','◎','Карта и переезд')}<div class="nav-label">ИСТОРИЯ</div>${nav('journal','▤','Журнал')}${nav('achievements','♜','Достижения')}<div class="nav-label">НАСТРОЙКИ</div><button class="nav-btn" data-action="backup">⇧ Резервная копия</button></nav><section class="content">${view==='home'?homeView():view==='career'?careerView():view==='money'?moneyView():view==='world'?worldView():view==='journal'?journalView():view==='family'?familyView():view==='health'?healthView():view==='relations'?relationsView():achievementsView()}</section></div>`;
 $('#nextMonth').onclick=()=>advance(1);$('#speed').onclick=()=>advance(3);$('#toEvent').onclick=()=>advanceUntilEvent();$('#pause').onclick=()=>toast('Время остановлено. Следующий месяц начнётся по нажатию.');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;renderGame()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>chooseEvent(+b.dataset.choice));document.querySelectorAll('[data-career-pick]').forEach(b=>b.onclick=()=>setCareer(+b.dataset.careerPick));document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buy(b.dataset.buy));document.querySelectorAll('[data-country]').forEach(b=>b.onclick=()=>relocate(+b.dataset.country));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('[data-category]').forEach(x=>x.style.display=(b.dataset.tab==='Все'||x.dataset.category===b.dataset.tab)?'':'none')});
}
function nav(v,ico,label){return `<button class="nav-btn ${view===v?'active':''}" data-view="${v}"><span>${ico}</span>${label}</button>`}
function homeView(){return `<div class="hero"><span class="eyebrow">ИСТОРИЯ ПРОДОЛЖАЕТСЯ</span><h1>Первые открытия</h1><p>Маленькие решения складываются в большую жизнь.</p><span class="avatar">${state.gender==='Женский'?'👩':'🧑'}</span></div><div class="grid-two"><article class="card"><h2>Прогноз · ${monthName()}</h2><p class="muted">Ожидаемый остаток на счёте</p><div class="forecast"><strong>${fmt(state.money)} ${esc(state.symbol)}</strong><span class="muted">Доход, расходы и важные события появятся здесь.</span></div><p class="muted">${state.age<6?'Первые открытия происходят с возрастом. Можно прожить следующий месяц.':state.age<18?'Учёба, друзья и новые интересы постепенно определят будущее.':'Решения о работе, семье и доме формируют ваш путь.'}</p><div class="quicklinks"><button class="link-btn" data-view="career">Учёба и карьера ↗</button><button class="link-btn" data-view="journal">Открыть журнал ↗</button></div></article><article class="card"><h3>Персонаж и имущество</h3><div class="list-row"><span>Образование</span><span class="pill">${esc(state.education)}</span></div><div class="list-row"><span>Жильё</span><span class="pill">${esc(state.house)}</span></div><div class="list-row"><span>Телефон</span><span class="pill">${esc(state.phone)}</span></div><div class="list-row"><span>Семья</span><span class="pill">${state.children} детей</span></div><h3 style="margin-top:18px">Ближайшие цели</h3><p class="muted">${state.goals[0]||'Создай свою цель во вкладке «Достижения».'}</p><button class="btn small ghost" data-action="goal">＋ Создать цель</button></article></div>${eventNow?eventCard():''}<div class="card"><h3>Что дальше?</h3><p class="muted">Время идёт только по твоей команде. События возникают время от времени и в важные моменты взросления.</p><div class="notice">Игра сохраняется в браузере автоматически раз в игровой год, а вручную — через меню сохранений.</div></div>`}
function eventCard(){return `<article class="card event-card"><span class="eyebrow">СОБЫТИЕ · ${monthName()}</span><h2>${esc(eventNow.title)}</h2><p>${esc(eventNow.text)}</p><div class="choice-list">${eventNow.choices.map((c,i)=>`<button class="choice" data-choice="${i}">${esc(c[0])}<small>${esc(c[1])}</small></button>`).join('')}</div></article>`}
function careerView(){return `<div class="card"><span class="eyebrow">РАЗВИТИЕ</span><h2>Учёба и карьера</h2><p class="muted">Можно менять путь. Звания, обучение, репутация и решения влияют на продвижение.</p>${state.age<6?`<div class="notice">До школьного возраста можно выбрать будущую карьеру или дождаться новых интересов.</div>`:''}<div class="tabs"><button class="tab-btn active" data-tab="Все">Все направления</button>${['Спорт','Творчество','Служба','Наука','Другое'].map(x=>`<button class="tab-btn" data-tab="${x}">${x}</button>`).join('')}</div><div class="career-select">${CAREERS.map((c,i)=>`<button class="career-option" data-category="${careerCategory(c[0])}" data-career-pick="${i}"><strong>${c[1]} ${c[0]} ${state.career===c[0]?'✓':''}</strong><small>${c[2]}</small></button>`).join('')}</div></div><div class="card"><h3>Учёба</h3><div class="list-row"><span>Школа</span><span class="pill">${state.age<6?'Ещё не началась':state.age<18?'Учится · оценки '+state.schoolGrade+'/5':state.education}</span></div><div class="list-row"><span>Интеллект</span><span class="pill">${Math.round(state.mind)} / 100</span></div><div class="modal-actions"><button class="btn ghost" data-action="study">📖 Учиться дополнительно</button><button class="btn ghost" data-action="train">🏃 Тренироваться</button><button class="btn ghost" data-action="exam">📝 Сдать экзамен</button></div></div>`}
function careerCategory(n){if(/Футбол|Бокс|Космонавт/.test(n))return 'Спорт';if(/Стример|блогер|Музыкант|Актёр/.test(n))return 'Творчество';if(/Полицейский|Пожарный|ФСБ|Армия|Политик|мафия|Хакер/.test(n))return 'Служба';if(/Учёный|Врач|Программист|Инженер/.test(n))return 'Наука';return 'Другое'}
function moneyView(){return `<div class="card"><span class="eyebrow">ФИНАНСЫ</span><h2>Имущество и деньги</h2><div class="forecast"><strong>Баланс: ${fmt(state.money)} ${esc(state.symbol)}</strong><span class="muted">Валюта отображения: ${state.symbol==='₽'?'рубли':'местная валюта'} · ${state.exchangeRate?'курс обновлён':'курс можно обновить при переезде'}</span></div><div class="tabs"><button class="tab-btn active" data-tab="Все">Все покупки</button>${['Телефоны','Машины','Жильё','Одежда'].map(x=>`<button class="tab-btn" data-tab="${x}">${x}</button>`).join('')}</div><div class="list-row" data-category="Телефоны"><span>📱 Простой телефон <small class="muted">Для связи</small></span><button class="btn small ghost" data-buy="phone1">12 000 ₽</button></div><div class="list-row" data-category="Телефоны"><span>📱 Смартфон <small class="muted">Полезен для работы и контента</small></span><button class="btn small ghost" data-buy="phone2">85 000 ₽</button></div><div class="list-row" data-category="Машины"><span>🚗 Городской автомобиль</span><button class="btn small ghost" data-buy="car1">1 200 000 ₽</button></div><div class="list-row" data-category="Машины"><span>🚙 Семейный автомобиль</span><button class="btn small ghost" data-buy="car2">3 000 000 ₽</button></div><div class="list-row" data-category="Жильё"><span>🏠 Небольшая квартира</span><button class="btn small ghost" data-buy="home1">7 000 000 ₽</button></div><div class="list-row" data-category="Жильё"><span>🏡 Просторный дом</span><button class="btn small ghost" data-buy="home2">18 000 000 ₽</button></div><div class="list-row" data-category="Одежда"><span>🧥 Тёплая зимняя одежда</span><button class="btn small ghost" data-buy="clothes">18 000 ₽</button></div><div class="modal-actions"><button class="btn ghost" data-action="credit">＋ Кредит</button><button class="btn ghost" data-action="sell">Продать имущество</button><button class="btn ghost" data-action="invest">Вложить деньги</button></div><div class="notice">В этой версии каталог покупок и экономика демонстрационные. Регулярные расходы, аренда, налоги и кредиты моделируются в событиях.</div></div>`}
function worldView(){return `<div class="card"><span class="eyebrow">МИР · КАРТА</span><h2>Путешествия и переезд</h2><p class="muted">Выбери страну для путешествия или нового дома. Курс валюты обновляется по запросу к открытой службе курсов, если есть интернет.</p><div class="modal-actions"><button class="btn ghost" data-action="rates">Обновить курс валют</button><button class="btn ghost" data-action="currency">Показывать рубли / местную валюту</button></div><div class="world-map">${COUNTRIES.map((c,i)=>`<button class="world-tile" data-country="${i}">🌐 ${esc(c.name)}<br><small>${c.currency} · ${c.cities.length} города</small></button>`).join('')}</div></div><div class="notice">Сейчас в игре представлены 30 стран и крупные города. Варианты городов подобраны как примеры; полный справочник населённых пунктов не подключён.</div>`}
function journalView(){return `<div class="card"><span class="eyebrow">ИСТОРИЯ</span><h2>Журнал жизни</h2><div class="modal-actions"><button class="btn ghost" data-action="exportStory">Скачать историю</button><button class="btn ghost" data-action="print">Печать</button><button class="btn ghost" data-action="chart">График показателей</button></div>${state.logs.map(l=>`<div class="log-entry"><time>${esc(l.date)}</time>${esc(l.text)}</div>`).join('')||'<p class="muted">Пока здесь пусто.</p>'}</div>`}
function familyView(){return `<div class="card"><span class="eyebrow">БЛИЗКИЕ</span><h2>Семья и альбом</h2><div class="list-row"><span>Семейное положение</span><span class="pill">${state.married?'В браке':'Не в браке'}</span></div><div class="list-row"><span>Дети</span><span class="pill">${state.children}</span></div><div class="list-row"><span>Питомец</span><span class="pill">${esc(state.pet)}</span></div><div class="modal-actions"><button class="btn ghost" data-action="date">♡ Провести время с близкими</button><button class="btn ghost" data-action="gift">🎁 Подарить подарок</button><button class="btn ghost" data-action="pet">🐾 Завести питомца</button><button class="btn ghost" data-action="family">Создать семью / дети</button></div><h3>Альбом памятных моментов</h3>${state.album.map(a=>`<div class="log-entry">📷 ${esc(a)}</div>`).join('')||'<p class="muted">Памятные события появятся здесь.</p>'}<button class="btn small ghost" data-action="note">＋ Заметка в альбом</button></div><div class="card"><h3>Семейное древо</h3><p>👤 ${esc(state.name)} ${esc(state.surname)} ${state.married?'♡ партнёр':''} ${state.children?'↓ '+state.children+' детей':''}</p></div>`}
function healthView(){return `<div class="card"><span class="eyebrow">САМОЧУВСТВИЕ</span><h2>Здоровье и привычки</h2><div class="list-row"><span>Здоровье</span><span class="pill">${Math.round(state.health)}%</span></div><div class="list-row"><span>Энергия</span><span class="pill">${Math.round(state.energy)}%</span></div><div class="list-row"><span>Настроение</span><span class="pill">${Math.round(state.mood)}%</span></div><div class="modal-actions"><button class="btn ghost" data-action="rest">🛏 Отдохнуть</button><button class="btn ghost" data-action="doctor">🩺 Сходить к врачу · 2 000 ₽</button><button class="btn ghost" data-action="sport">⚽ Заняться спортом</button></div><div class="notice">Здоровье, усталость, погода и одежда могут менять самочувствие.</div></div>`}
function relationsView(){return `<div class="card"><span class="eyebrow">ОТНОШЕНИЯ</span><h2>Люди рядом</h2><div class="list-row"><span>Семья</span><span class="pill">${Math.round(state.relations)} / 100</span></div><div class="list-row"><span>Друзья</span><span class="pill">${Math.round(state.relations*0.8)} / 100</span></div><div class="list-row"><span>Романтические отношения</span><span class="pill">${state.married?'Семья создана':'Можно познакомиться'}</span></div><div class="modal-actions"><button class="btn ghost" data-action="friend">Познакомиться с другом</button><button class="btn ghost" data-action="date">Пойти на свидание</button><button class="btn ghost" data-action="family">Провести время с семьёй</button><button class="btn ghost" data-action="gift">Подарить подарок</button></div><p class="muted">Репутация: ${Math.max(0,state.reputation)} · поступки влияют на людей и карьеру.</p></div>`}
function achievementsView(){return `<div class="card"><span class="eyebrow">ЦЕЛИ И УСПЕХИ</span><h2>Достижения и цели</h2><button class="btn ghost" data-action="goal">＋ Создать свою цель</button><h3 style="margin-top:18px">Личные цели</h3>${state.goals.map(g=>`<div class="list-row"><span>🎯 ${esc(g)}</span><span class="pill">В процессе</span></div>`).join('')||'<p class="muted">Добавь любую цель — от путешествия до новой работы.</p>'}<h3 style="margin-top:18px">Достижения</h3>${state.achievements.map(a=>`<div class="list-row"><span>🏅 ${esc(a)}</span><span class="pill good">Получено</span></div>`).join('')||'<p class="muted">Первые достижения появятся в ходе жизни.</p>'}</div>`}
function chooseCareer(i){if(state.age<14&&CAREERS[i][0]!=='Обычная работа'){if(!confirm('Персонаж ещё молод. Записать это как будущую мечту?'))return;}setCareer(i)}function setCareer(i){let c=CAREERS[i][0];if(state.career===c){toast('Этот путь уже выбран');return}if(state.career!=='Без карьеры'&&state.career!==c){state.reputation=Math.max(0,state.reputation-1);log(`Сменил карьерный путь: ${c}.`)}else log(`Выбрал карьеру: ${c}.`);state.career=c;state.jobLevel=0;state.careerRank=c==='Футболист'?'Кандидат в академию':c==='Политик'?'Начинающий участник':c==='Вор / мафия'?'Новичок':c==='Без карьеры'?'Не выбрана':'Стажёр / новичок';state.album.push(`Начало пути: ${c}`);persist();renderGame();toast('Карьерный путь выбран')}
function advance(n){if(state.dead)return;for(let i=0;i<n;i++){state.month++;if(state.month>=12){state.month=0;state.year++;state.age++;annualTick()}monthlyTick();if(Math.random()<(state.eventDifficulty==='Спокойная'?.1:state.eventDifficulty==='Непредсказуемая'?.29:.19)){eventNow=EVENTS[Math.floor(Math.random()*EVENTS.length)]}if(state.age===6){eventNow={title:'Первый школьный день',text:'Пора идти в школу. Учёба, друзья и новые навыки откроют разные дороги.',choices:[['Учиться прилежно','Ум +5, энергия −2',s=>{s.mind=clamp(s.mind+5);s.energy=clamp(s.energy-2)}],['Больше общаться','Отношения +5, настроение +3',s=>{s.relations=clamp(s.relations+5);s.mood=clamp(s.mood+3)}]]};log('Пошёл в школу.')}if(state.age===18){eventNow={title:'Взрослая жизнь',text:'Открываются новые дороги: учёба, первая работа, карьера и самостоятельная жизнь.',choices:[['Искать работу','Репутация +1',s=>s.reputation++],['Продолжить учёбу','Ум +4',s=>s.mind=clamp(s.mind+4)]]};log('Наступило совершеннолетие.')}if(state.age>=100){endLife();break}}persist();renderGame();if(eventNow){document.querySelector('.content')?.scrollIntoView({behavior:'smooth',block:'end'})}}
function monthlyTick(){const seasonal=state.month>=10||state.month<=2;if(seasonal&&state.clothes!=='Тёплая зимняя одежда'){state.health=clamp(state.health-1);if(Math.random()<.15)log('Похолодало, не хватило тёплой одежды.')}state.energy=clamp(state.energy-2);state.mood=clamp(state.mood+(state.relations>35?1:-1));if(state.career!=='Без карьеры'&&state.age>=16){let income=careerIncome();state.money+=income;log(`Получен доход за месяц: ${fmt(income)} ${state.symbol}.`)}if(state.house!=='Съёмная комната'&&state.age>=18)state.money-=3500;if(state.money<0&&Math.random()<.12){state.reputation=Math.max(0,state.reputation-1);log('Денег не хватило на обязательные расходы.')}if(Math.random()<.04&&state.health<45){state.health=clamp(state.health-5);log('Самочувствие ухудшилось: нужен отдых или врач.')}}
function annualTick(){if(state.autosave){state.savedAt=Date.now();persist();toast('Годовое автосохранение готово')}state.statsHistory.push({year:state.year,health:state.health,mind:state.mind,mood:state.mood,money:state.money,reputation:state.reputation});if(state.statsHistory.length>60)state.statsHistory.shift();if(state.career==='Бизнесмен'){let opts=['Нанять сотрудника','Вложиться в рекламу','Запустить новый проект'];if(Math.random()<.4){state.money+=Math.random()<.55?25000:-12000;log(`Бизнес-год: ${opts[Math.floor(Math.random()*opts.length)]}.`);state.reputation=Math.max(0,state.reputation+1)}}if(state.career==='Футболист'&&state.age>=18){state.jobLevel=Math.min(5,state.jobLevel+1);state.careerRank=['Академия','Молодёжная команда','Игрок основы','Основной состав','Капитан клуба','Звезда лиги'][state.jobLevel];log(`Футбольная карьера: ${state.careerRank}.`)}if(state.career!=='Без карьеры'&&state.career!=='Футболист'){state.jobLevel=Math.min(state.jobLevel+1,5);state.careerRank=['Стажёр / новичок','Младший специалист','Специалист','Старший специалист','Руководитель отдела','Опытный руководитель'][state.jobLevel];if(Math.random()<.3){state.reputation++;log(`Продвижение по карьере: ${state.careerRank}.`)}}if(Math.random()<.18){state.achievements.push(`Новый год жизни · ${state.age} лет`);state.album.push(`День рождения · ${state.age} лет`);log(`Персонажу исполнилось ${state.age} лет.`)}}
function careerIncome(){let base=state.career==='Футболист'?8000:state.career==='Стример'||state.career==='Видеоблогер'?3500:state.career==='Бизнесмен'?11000:state.career==='Политик'?9000:9000;return Math.round(base+state.jobLevel*2500+state.reputation*60)}function chooseEvent(i){if(!eventNow)return;let c=eventNow.choices[i];c[2](state);log(`${eventNow.title}: ${c[0]}.`);state.album.push(eventNow.title);if(state.album.length>100)state.album.shift();eventNow=null;persist();renderGame();toast('Решение записано в журнал')}
function advanceUntilEvent(){for(let i=0;i<12&&!eventNow;i++)advance(1);if(!eventNow)toast('В ближайшее время крупных событий нет')}
function endLife(){state.dead=true;persist();view='home';openModal('ИТОГ ИСТОРИИ','Жизнь завершилась',`<div class="life-ended"><div class="big">🕯</div><p>${esc(state.name)} прожил(а) ${state.age} лет.</p><p>Карьера: ${esc(state.career)} · Достижений: ${state.achievements.length}</p><button class="btn primary" data-close>Посмотреть историю</button></div>`);log('История жизни завершилась.');}
function buy(type){const items={phone1:['Простой телефон',12000,'phone'],phone2:['Смартфон',85000,'phone'],car1:['Городской автомобиль',1200000,'car'],car2:['Семейный автомобиль',3000000,'car'],home1:['Небольшая квартира',7000000,'house'],home2:['Просторный дом',18000000,'house'],clothes:['Тёплая зимняя одежда',18000,'clothes']};let [n,c,k]=items[type];if(state.money<c){toast('Пока не хватает денег');return}state.money-=c;state[k]=n;log(`Куплено: ${n}.`);state.achievements.push(`Покупка: ${n}`);persist();renderGame();toast('Покупка сделана')}
function action(a){switch(a){case'backup':backup();return;case'goal':{let g=prompt('Какую цель поставить персонажу?');if(g?.trim()){state.goals.push(g.trim());persist();renderGame()}return}case'study':state.mind=clamp(state.mind+5);state.energy=clamp(state.energy-4);log('Дополнительно занимался учёбой.');break;case'train':case'sport':state.energy=clamp(state.energy-6);state.health=clamp(state.health+3);state.mood=clamp(state.mood+3);log('Занимался спортом.');break;case'exam':if(state.mind>45){state.schoolGrade=Math.min(5,state.schoolGrade+1);state.reputation++;toast('Экзамен сдан хорошо!')}else toast('Стоит сначала позаниматься.');break;case'rest':state.energy=clamp(state.energy+20);state.mood=clamp(state.mood+4);break;case'doctor':if(state.money<2000){toast('Не хватает денег на приём');return}state.money-=2000;state.health=clamp(state.health+15);log('Посетил врача.');break;case'date':state.relations=clamp(state.relations+6);state.mood=clamp(state.mood+5);break;case'friend':state.relations=clamp(state.relations+4);state.mood=clamp(state.mood+2);log(`Познакомился с ${['Анной','Артёмом','Мией','Даниилом','Софией'][Math.floor(Math.random()*5)]}.`);break;case'gift':if(state.money<1000){toast('Не хватает денег на подарок');return}state.money-=1000;state.relations=clamp(state.relations+8);log('Подарил близкому человеку подарок.');break;case'pet':if(state.pet!=='Нет питомца'){toast('У персонажа уже есть питомец');return}if(state.money<5000){toast('Нужно 5 000 ₽ на питомца и первые покупки');return}state.money-=5000;state.pet=['Кот','Собака','Попугай'][Math.floor(Math.random()*3)];state.mood=clamp(state.mood+8);log(`В семье появился питомец: ${state.pet}.`);break;case'family':if(state.age<18){toast('Семья — решение для взрослой жизни');return}if(!state.married){state.married=true;state.relations=clamp(state.relations+8);log('Создал семью.')}else{state.children++;state.money-=5000;log('В семье появился ребёнок.')}break;case'credit':if(state.money<0){toast('Сначала разберись с текущими долгами');return}state.money+=100000;log('Оформлен игровой кредит 100 000 ₽. Ежемесячное погашение начнётся позже.');state.reputation=Math.max(0,state.reputation-1);break;case'sell':if(state.car==='Нет машины'&&state.house==='Съёмная комната'){toast('Пока нечего продавать');return}if(state.car!=='Нет машины'){state.money+=600000;state.car='Нет машины';log('Продал машину.')}else{state.money+=3500000;state.house='Съёмная комната';log('Продал жильё.')}break;case'invest':if(state.money<5000){toast('Нужно хотя бы 5 000 ₽');return}state.money-=5000;if(Math.random()<.5){state.money+=12000;toast('Вложение принесло прибыль')}else toast('Вложение оказалось неудачным');log('Попробовал рискованное вложение.');break;case'currency':state.symbol=state.symbol==='₽'?COUNTRIES.find(c=>c.name===state.country).symbol:'₽';toast(`Отображение: ${state.symbol}`);break;case'rates':updateRates();return;case'exportStory':exportStory();return;case'print':window.print();return;case'chart':showChart();return;case'note':{let n=prompt('Заметка к альбому:');if(n?.trim())state.album.unshift(n.trim());break}default:return}persist();renderGame()}
async function updateRates(){let c=COUNTRIES.find(x=>x.name===state.country);if(!c){toast('Страна не найдена');return}try{let res=await fetch(`https://api.frankfurter.dev/v1/latest?base=${state.currency}&symbols=RUB`);if(!res.ok)throw new Error();let d=await res.json();state.exchangeRate=d.rates.RUB;log(`Обновлён курс ${state.currency}/RUB: ${state.exchangeRate}.`);persist();renderGame();toast(`Курс обновлён: 1 ${state.currency} = ${state.exchangeRate} ₽`)}catch{toast('Не удалось получить курс. Проверь интернет и попробуй снова.')}}
function relocate(i){let c=COUNTRIES[i];if(c.name===state.country){toast('Персонаж уже здесь');return}let cost=Math.max(5000,Math.round(25000+Math.random()*45000));if(state.money<cost){toast(`На переезд нужно около ${fmt(cost)} ${state.symbol}`);return}if(!confirm(`Переехать в ${c.name}, город ${c.cities[0]}? Переезд стоит около ${fmt(cost)} ${state.symbol}.`))return;state.money-=cost;state.country=c.name;state.city=c.cities[Math.floor(Math.random()*c.cities.length)];state.currency=c.currency;state.language=c.lang;state.relations=clamp(state.relations-5);log(`Переехал в ${state.city}, ${c.name}. Начал изучать язык: ${c.lang}.`);state.album.push(`Переезд в ${state.city}, ${c.name}`);persist();renderGame();toast('Переезд состоялся')}
function openSlots(){let ss=slots(),keys=Object.keys(ss);openModal('СОХРАНЕНИЯ','Семьи и прохождения',`<div class="modal-actions"><button class="btn primary" id="saveNow">Сохранить текущую жизнь</button><button class="btn ghost" id="newLife">Новая жизнь</button><button class="btn ghost" id="importSave">Загрузить резервную копию</button></div>${keys.map(k=>`<div class="list-row"><span><b>${esc(k)}</b><small class="muted" style="display:block">${esc(ss[k].name)} · ${ss[k].age} лет · ${esc(ss[k].country)}</small></span><span><button class="btn small ghost" data-load="${esc(k)}">Загрузить</button> <button class="btn small ghost" data-rename="${esc(k)}">Переименовать</button></span></div>`).join('')||'<p class="muted">Пока нет сохранённых жизней.</p>'}`);$('#saveNow').onclick=()=>{let k=prompt('Название сохранения',state.slot||'Жизнь 1');if(!k?.trim())return;state.slot=k.trim();persist();dlg.close();toast('Сохранение готово')};$('#newLife').onclick=()=>{dlg.close();state=null;renderSetup()};$('#importSave').onclick=()=>importBackup();document.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>{state=ss[b.dataset.load];localStorage.setItem('lifeActive',JSON.stringify(state));view='home';dlg.close();renderGame()});document.querySelectorAll('[data-rename]').forEach(b=>b.onclick=()=>{let n=prompt('Новое название',b.dataset.rename);if(n?.trim()){let z=slots(),v=z[b.dataset.rename];delete z[b.dataset.rename];z[n.trim()]=v;v.slot=n.trim();localStorage.setItem('lifeSlots',JSON.stringify(z));if(state.name===v.name)state.slot=n.trim();persist();openSlots()}})}
function backup(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});download(blob,`${safeFile(state.name)}-backup.json`);toast('Резервная копия скачана')}function importBackup(){let f=document.createElement('input');f.type='file';f.accept='.json,application/json';f.onchange=()=>{let file=f.files[0];if(!file)return;let r=new FileReader();r.onload=()=>{try{state=JSON.parse(r.result);state.slot=state.slot||'Импортированная жизнь';persist();dlg.close();renderGame();toast('Резервная копия загружена')}catch{toast('Не получилось прочитать файл')}};r.readAsText(file)};f.click()}
function exportStory(){let txt=`ИСТОРИЯ ЖИЗНИ: ${state.name} ${state.surname}\n${state.age} лет · ${state.city}, ${state.country}\nКарьера: ${state.career} (${state.careerRank})\n\n`+state.logs.map(x=>`${x.date}: ${x.text}`).join('\n');download(new Blob([txt],{type:'text/plain;charset=utf-8'}),`${safeFile(state.name)}-история.txt`)}function safeFile(s){return String(s).toLowerCase().replace(/[^a-zа-яё0-9]+/gi,'-')||'life'}function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function showChart(){let h=state.statsHistory.slice(-10);if(!h.length){toast('График появится после первого игрового года');return}openModal('ПОКАЗАТЕЛИ','Как менялась жизнь',`<p class="muted">Здоровье персонажа по годам.</p><div class="bar-chart">${h.map(x=>`<div class="bar" style="height:${Math.max(3,x.health)}%" title="${x.year}: ${Math.round(x.health)}%"><span>${x.year}</span></div>`).join('')}</div><div class="list-row"><span>Ум</span><span>${Math.round(state.mind)} / 100</span></div><div class="list-row"><span>Настроение</span><span>${Math.round(state.mood)} / 100</span></div><div class="list-row"><span>Деньги</span><span>${fmt(state.money)} ${esc(state.symbol)}</span></div>`)}
function help(){openModal('КРАТКАЯ СПРАВКА','Как играть',`<div class="list-row"><b>Время</b><span>Идёт только после кнопки месяца или ускорения.</span></div><div class="list-row"><b>События</b><span>Появляются случайно и на возрастных этапах.</span></div><div class="list-row"><b>Карьера</b><span>Выбирается во вкладке развития; прогресс пока демонстрационный.</span></div><div class="list-row"><b>Сохранения</b><span>Хранятся в браузере. Резервную копию можно скачать в JSON.</span></div><div class="notice">Для актуального курса валют нужен интернет. Игра запускается локально, но Google Fonts и курсы могут не загрузиться без сети.</div>`)}
$('#menuBtn').onclick=()=>state?.name?openSlots():openSlots();$('#helpBtn').onclick=help;$('#themeBtn').onclick=()=>{document.body.classList.toggle('dark');if(state){state.dark=document.body.classList.contains('dark');persist()}};$('#soundBtn').onclick=()=>{if(state){state.sound=!state.sound;persist()}toast(state?.sound?'Звук включён (демо-версия без музыки)':'Звук выключен')};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dlg.open)dlg.close();if(e.key==='Enter'&&e.ctrlKey)advance(1)});if(state?.dark)document.body.classList.add('dark');init();

// Feedback patch: age-appropriate beginnings, birthday calendar, fatigue and childhood interests.
const baseStartGame=startGame, baseRenderGame=renderGame, baseCareerView=careerView, baseAction=action, baseSetCareer=setCareer, baseAnnualTick=annualTick;
startGame=function(){const chosenMonth=Number($('#birthMonth').value),chosenDay=Math.max(1,Math.min(31,Number($('#birthDay').value)||1));baseStartGame();state.month=chosenMonth;state.birthMonth=chosenMonth;state.birthDay=chosenDay;state.year=2026;state.health=62;state.mind=8;state.mood=72;state.energy=75;state.fatigue=0;state.relations=8;state.reputation=0;state.familyFunds=state.money;state.money=0;state.career='Без карьеры';state.careerRank='Не выбрана';state.jobLevel=0;persist();renderGame();};
careerView=function(){return baseCareerView().replace(/<div class="career-select">[\s\S]*?<\/div><\/div><div class="card"><h3>Учёба<\/h3>/,`<div class="career-select">${CAREERS.map((c,i)=>({c,i})).filter(({c})=>careerAllowed(c[0],state.age)).map(({c,i})=>`<button class="career-option" data-category="${careerCategory(c[0])}" data-career-pick="${i}"><strong>${c[1]} ${c[0]} ${state.career===c[0]?'✓':''}</strong><small>${c[2]}</small></button>`).join('')}</div></div><div class="card"><h3>Учёба</h3>`).replace('<div class="modal-actions"><button class="btn ghost" data-action="study">','<div class="modal-actions"><button class="btn ghost" data-action="school">🏫 Пойти на занятия · −10 энергии</button><button class="btn ghost" data-action="study">');};
function careerAllowed(name,age){if(age<6)return ['Футболист','Художник','Музыкант'].includes(name);if(age<13)return ['Футболист','Художник','Музыкант','Актёр'].includes(name);if(age<18)return ['Футболист','Художник','Музыкант','Актёр','Стример','Видеоблогер'].includes(name);return true}
setCareer=function(i){const c=CAREERS[i];if(!c||!careerAllowed(c[0],state.age)){toast('Эта карьера станет доступна позже');return}baseSetCareer(i);if(state.age<14){state.careerRank='Детское увлечение';log(`Пока это увлечение: ${c[0]}.`);persist();renderGame()}};
annualTick=function(){state.statsHistory.push({year:state.year,health:state.health,mind:state.mind,mood:state.mood,money:state.money,reputation:state.reputation});if(state.statsHistory.length>60)state.statsHistory.shift();if(state.autosave){state.savedAt=Date.now();persist();toast('Годовое автосохранение готово')}if(state.age===6)log('Пошёл в школу.');if(state.age===14)log('Теперь можно искать подработку и заводить друзей.');if(state.age===18){log('Наступила взрослая жизнь.');if(!state.adultGrant){let grant=Math.min(50000,Math.round((state.familyFunds||0)*.1));state.money+=grant;state.familyFunds=Math.max(0,(state.familyFunds||0)-grant);state.adultGrant=true;if(grant)log(`Семья помогла начать самостоятельную жизнь: ${fmt(grant)} ${state.symbol}.`)}}if(state.age>=6&&state.age<18&&state.career==='Без карьеры'&&state.mind>60)state.schoolGrade=Math.min(5,state.schoolGrade+1);if(state.career==='Бизнесмен'&&state.age>=18&&Math.random()<.4){state.money+=Math.random()<.55?25000:-12000;log('Годовое решение бизнеса повлияло на прибыль.')}if(state.career!=='Без карьеры'&&state.age>=18&&state.career!=='Футболист'){state.jobLevel=Math.min(5,state.jobLevel+1);state.careerRank=['Стажёр / новичок','Младший специалист','Специалист','Старший специалист','Руководитель отдела','Опытный руководитель'][state.jobLevel];if(Math.random()<.35)log(`Продвижение: ${state.careerRank}.`)}if(state.career==='Футболист'&&state.age>=14){state.careerRank=state.age<18?'Футбольная академия · молодёжная команда':'Игрок клуба · '+['Академия','Молодёжная команда','Игрок основы','Основной состав','Капитан клуба','Звезда лиги'][Math.min(5,++state.jobLevel)];log(`Футбол: ${state.careerRank}.`)}if(state.age>0){state.achievements.push(`Новый год жизни · ${state.age} лет`);state.album.push(`День рождения · ${state.age} лет`)}};
monthlyTick=function(){state.fatigue=clamp((state.fatigue||0)+6);state.energy=clamp(state.energy+18);if(state.age>=14&&state.career==='Подработка'){state.money+=3500;state.energy=clamp(state.energy-4);log('Получил деньги за подработку.')}const cold=state.month>=10||state.month<=2;if(cold&&state.clothes!=='Тёплая зимняя одежда'&&(state.care??100)<20)state.health=clamp(state.health-0.2);if(state.pet!=='Нет питомца')state.money-=500;if(state.career!=='Без карьеры'&&state.career!=='Подработка'&&state.age>=18){let income=careerIncome();state.money+=income;log(`Доход за месяц: ${fmt(income)} ${state.symbol}.`)}if(state.house!=='Съёмная комната'&&state.age>=18)state.money-=3500;if(state.age<3)state.relations=clamp(state.relations+1);state.mood=clamp(state.mood+(state.relations>35?1:-1));if(state.fatigue>85)state.mood=clamp(state.mood-2);if(state.health<35&&Math.random()<.08)state.health=clamp(state.health-2)};
advance=function(n){if(state.dead)return;if(state.energy<5){toast('Сил почти не осталось. Отдохни перед следующим месяцем.');return}for(let i=0;i<n;i++){const next=(state.month+1)%12;state.month=next;if(next===0)state.year++;const birthdayMonth=Number(state.birthMonth??0);if(next===birthdayMonth){state.age++;annualTick()}monthlyTick();if(Math.random()<(state.eventDifficulty==='Спокойная'?.1:state.eventDifficulty==='Непредсказуемая'?.29:.19))eventNow=EVENTS[Math.floor(Math.random()*EVENTS.length)];if(state.age===6)eventNow={title:'Первый школьный день',text:'Начинается школа. Можно учиться, заводить друзей и пробовать занятия после уроков.',choices:[['Стараться в учёбе','Ум +5, усталость +3',s=>{s.mind=clamp(s.mind+5);s.fatigue=clamp(s.fatigue+3)}],['Записаться на футбол','Открывается футбольная академия позже',s=>{s.career='Футболист';s.careerRank='Детское увлечение'}],['Рисовать и ходить в кружок','Настроение +5, ум +2',s=>{s.mood=clamp(s.mood+5);s.mind=clamp(s.mind+2)}]]};if(state.age===14)eventNow={title:'Можно найти подработку',text:'С четырнадцати лет персонаж может искать простую подработку и откладывать часть денег.',choices:[['Начать подрабатывать','Доход 3 500 ₽ в месяц, энергия −4',s=>{s.career='Подработка';s.careerRank='Подростковая подработка'}],['Сосредоточиться на учёбе','Ум +5',s=>s.mind=clamp(s.mind+5)]]};if(state.age===18)eventNow={title:'Взрослая жизнь',text:'Теперь открыты взрослые карьеры, переезд, учёба и самостоятельные решения.',choices:[['Выбрать карьеру','Открыть список профессий',s=>{}],['Продолжить учёбу','Ум +4',s=>s.mind=clamp(s.mind+4)]]};if(state.age>=100){endLife();break}}persist();renderGame()};
action=function(a){if(a==='school'){if(state.age<6||state.age>=18){toast('Школа доступна с 6 до 17 лет');return}if(state.energy<10){toast('Нужно хотя бы 10 энергии. Отдохни.');return}state.energy=clamp(state.energy-10);state.mind=clamp(state.mind+3);state.fatigue=clamp(state.fatigue+4);log('Сходил на дополнительные занятия: ум +3, энергия −10.');persist();renderGame();return}if(a==='rest'){state.energy=clamp(state.energy+25);state.fatigue=clamp(state.fatigue-20);state.mood=clamp(state.mood+5);log('Отдохнул: энергия восстановилась, усталость снизилась.');persist();renderGame();return}if(a==='date'&&state.age<14){toast('Романтические отношения доступны с 14 лет');return}if(a==='study'&&state.age<6){toast('Учёба начнётся в 6 лет. Пока можно выбрать футбол или рисование.');return}baseAction(a);};
renderGame=function(){if(!state)return;state.fatigue??=0;state.birthMonth??=0;state.birthDay??=1;if(!state.statsRevision&&state.age<=2){state.health=62;state.mind=8;state.energy=75;state.fatigue=0;state.relations=8+state.age*2;state.familyFunds??=state.money;state.money=0;state.statsRevision=2;persist()}state.fatigue??=0;state.familyFunds??=0;baseRenderGame();const moneyCard=document.querySelector('.metric.money');if(moneyCard&&state.age<14){const label=moneyCard.querySelector('.metric-name span:first-child'),caption=moneyCard.querySelector('.muted');if(label)label.textContent='Личные деньги';if(caption)caption.textContent='Личный счёт персонажа'}const ms=document.querySelectorAll('.game-top .metric');if(ms[4]){ms[4].innerHTML=metric('Усталость',state.fatigue);ms[4].insertAdjacentHTML('afterend',metric('Энергия',state.energy))}if(view==='home'&&state.age<18){const forecast=document.querySelector('.content .forecast');if(forecast)forecast.insertAdjacentHTML('afterend',`<div class="list-row family-budget"><span>Семейный бюджет</span><b>${fmt(state.familyFunds)} ${esc(state.symbol)}</b></div>`)}const turn=document.querySelector('.turn-date');if(turn?.firstChild)turn.firstChild.textContent=`${state.age} лет · ${state.birthDay} ${monthName()} ${state.year} `;const cert=document.querySelector('#modalContent .forecast');if(cert)cert.innerHTML=`Дата рождения: <b>${state.birthDay} ${monthName()} ${state.year} года</b><br>На свет появился <b>${esc(state.name)} ${esc(state.surname)}</b>, город ${esc(state.city)}, ${esc(state.country)}.`;const avatar=document.querySelector('.hero .avatar');if(avatar)avatar.innerHTML=`<span class="portrait ${state.age<6?'baby':state.age<14?'child':state.age<25?'teen':state.age<60?'adult':'elder'}"><i class="hair"></i><i class="face"></i><i class="body"></i></span>`;document.querySelectorAll('[data-career-pick]').forEach(b=>{const c=CAREERS[Number(b.dataset.careerPick)];if(c&&!careerAllowed(c[0],state.age))b.remove()});const dateBtns=document.querySelectorAll('[data-action="date"]');dateBtns.forEach(b=>{if(state.age<14)b.disabled=true});};
const priorStartForCertificate=startGame, priorActionForActivities=action, priorRenderForDetails=renderGame;
