action=function(a){if(a==='activityWork'&&state.age>=14&&state.age<18){if(state.energy<15){toast('Нужно 15 энергии, чтобы пойти на подработку.');return}state.energy-=15;state.fatigue=clamp(state.fatigue+4);state.money+=3500;state.career='Подработка';state.careerRank='Подростковая подработка';log('Подработал и отложил 3 500 ₽.');persist();renderGame();return}actionLatest(a)};
