function stageName(){return state.age<3?'Первые годы':state.age<6?'Дошкольные годы':state.age<14?'Школьные годы':state.age<18?'Подростковый период':'Самостоятельная жизнь'}
function stageText(){return state.age<3?'Первые слова, игры и семейные встречи. Небольшие действия требуют энергии.':state.age<6?'Рисунки, игры и первые совместные дела.':state.age<14?'Школа, друзья, кружки и новые увлечения.':state.age<18?'Учёба, первые подработки и важные решения.':'Работа, отношения, покупки и планы на будущее.'}
function ageActivities(){if(state.age<3)return [['activityPlay','Поиграть вместе','Немного времени с близким человеком.','5'],['activityToy','Поискать игрушку','Попросить взрослого помочь найти любимую игрушку.','15'],['activityAdult','Позвать взрослого','Попросить помощи или рассказать, что случилось.','8'],['rest','Отдохнуть','Перевести дух и восстановить силы к следующему месяцу.','5']];if(state.age<6)return [['activityPlay','Поиграть','Игры помогают настроению и близости.','5'],['activityDraw','Рисовать','Развивать воображение и сохранить рисунок в альбоме.','8'],['activityAdult','Попросить помощи','Обсудить с взрослым трудную ситуацию.','8'],['rest','Отдохнуть','Перевести дух и восстановить силы к следующему месяцу.','5']];if(state.age<14)return [['school','Пойти на занятия','Учёба развивает ум, но тратит силы.','10'],['activitySport','Потренироваться','Футбол, подвижная игра или секция.','12'],['activityDraw','Заняться творчеством','Рисование, музыка или кружок.','8'],['activityPlay','Провести время с друзьями','Общение укрепляет дружбу и настроение.','5'],['rest','Отдохнуть','Перевести дух и восстановить силы к следующему месяцу.','5']];if(state.age<18)return [['school','Пойти на занятия','Учёба развивает ум.','10'],['activityWork','Пойти на подработку','Заработать и отложить деньги.','15'],['activitySport','Потренироваться','Спорт развивает форму.','12'],['activityFriend','Встретиться с другом','Провести время вместе.','6'],['rest','Отдохнуть','Перевести дух и восстановить силы к следующему месяцу.','5']];return [['activityWork','Пойти на работу','Заработать и продвинуться в выбранном деле.','15'],['activitySport','Потренироваться','Поддерживать форму и здоровье.','12'],['activityFriend','Увидеться с близкими','Укрепить отношения.','6'],['rest','Отдохнуть','Перевести дух и восстановить силы к следующему месяцу.','5']]}
homeView=function(){const s=state;return `<div class="hero"><span class="eyebrow">${stageName().toUpperCase()}</span><h1>${stageName()}</h1><p>${stageText()}</p><span class="avatar"></span></div><div class="forecast"><strong>Прогноз · ${monthName()}</strong><span>${s.age<14?'Семейный бюджет': 'Ожидаемый остаток на счёте'}: ${fmt(s.age<14?s.familyFunds||0:s.money)} ${esc(s.symbol)}</span></div><div class="child-actions"><span class="eyebrow">ПО ЖЕЛАНИЮ</span><h2>Выбрать занятие</h2><div class="activity-grid">${ageActivities().map(a=>`<button class="activity-card" data-action="${a[0]}"><span class="activity-icon">${a[0]==='rest'?'♡':a[0]==='school'?'▤':a[0].includes('Sport')?'⚽':a[0].includes('Draw')?'✎':a[0].includes('Toy')?'⌕':'♧'}</span><span><b>${a[1]}</b><small>${a[2]}</small><em>ϟ ${a[3]} энергии</em></span></button>`).join('')}</div></div>${eventNow?eventCard():''}<details class="memory-panel"><summary>Показатели и воспоминания</summary><div class="memory-grid"><div><b>Интеллект</b><span>${Math.round(s.mind)} / 100</span><div class="meter"><span style="width:${clamp(s.mind)}%"></span></div></div><div><b>Харизма</b><span>${Math.round(s.charisma||15)} / 100</span><div class="meter"><span style="width:${clamp(s.charisma||15)}%"></span></div></div><div><b>Фитнес</b><span>${Math.round(s.fitness||20)} / 100</span><div class="meter"><span style="width:${clamp(s.fitness||20)}%"></span></div></div><div><b>Внешность</b><span>${Math.round(s.appearance||50)} / 100</span><div class="meter"><span style="width:${clamp(s.appearance||50)}%"></span></div></div></div><h3>Недавние воспоминания</h3>${s.logs.slice(0,4).map(l=>`<div class="log-entry"><time>${esc(l.date)}</time>${esc(l.text)}</div>`).join('')||'<p class="muted">История только начинается.</p>'}</details><div class="quicklinks"><button class="link-btn" data-view="family">Занятия и альбом ↗</button><button class="link-btn" data-view="journal">Открыть журнал ↗</button></div>`};
monthlyTick=function(){priorMonthlyTick2();if(state.resting){state.energy=clamp(state.energy+24);state.fatigue=clamp(state.fatigue-18);state.resting=false;log('После отдыха силы восстановились.')}if(state.age>=14&&state.career==='Подработка'){state.money+=3500;log('Получил 3 500 ₽ за подработку и отложил деньги.')}};
advance=function(n){if(state.dead)return;for(let i=0;i<n;i++){const next=(state.month+1)%12;state.month=next;if(next===0)state.year++;if(next===Number(state.birthMonth??0)){state.age++;annualTick()}monthlyTick();if(Math.random()<.14){if(state.age<3)eventNow={title:'Потерялась любимая игрушка',text:'Петя не может найти любимую игрушку. Можно помочь ему или позвать взрослого.',choices:[['Пообщаться и поиграть · 5 энергии','Близость +6',s=>{s.energy=clamp(s.energy-5);s.relations=clamp(s.relations+6);s.mood=clamp(s.mood+2)}],['Искать игрушку вместе · 15 энергии','Близость +10 · Физподготовка +1',s=>{s.energy=clamp(s.energy-15);s.relations=clamp(s.relations+10);s.fitness=clamp((s.fitness||20)+1)}],['Позвать взрослого · 8 энергии','Близость +10 · Харизма +1',s=>{s.energy=clamp(s.energy-8);s.relations=clamp(s.relations+10);s.charisma=clamp((s.charisma||15)+1)}]]};else if(state.age<6)eventNow={title:'Новая игра',text:'Можно попробовать новую игру или порисовать вместе.',choices:[['Поиграть · 5 энергии','Настроение +5 · Близость +4',s=>{s.energy=clamp(s.energy-5);s.mood=clamp(s.mood+5);s.relations=clamp(s.relations+4)}],['Нарисовать картинку · 8 энергии','Интеллект +2 · Настроение +3',s=>{s.energy=clamp(s.energy-8);s.mind=clamp(s.mind+2);s.mood=clamp(s.mood+3);s.album.unshift('Нарисовал картинку')}]]};else eventNow=EVENTS[Math.floor(Math.random()*EVENTS.length)]}if(state.age===6)eventNow={title:'Первый школьный день',text:'Пора идти в школу. Учёба, друзья и новые увлечения откроют разные дороги.',choices:[['Стараться в учёбе · 10 энергии','Ум +5',s=>{s.energy=clamp(s.energy-10);s.mind=clamp(s.mind+5)}],['Записаться на футбол','Открывается футбольная академия позже',s=>{s.career='Футболист';s.careerRank='Детское увлечение'}],['Начать рисовать','Настроение +5 · Интеллект +2',s=>{s.mood=clamp(s.mood+5);s.mind=clamp(s.mind+2);s.career='Художник';s.careerRank='Детское увлечение'}]]};if(state.age===14)eventNow={title:'Первые деньги',text:'С четырнадцати лет можно найти подработку и откладывать заработанное.',choices:[['Начать подрабатывать','Зарплата 3 500 ₽ в месяц',s=>{s.career='Подработка';s.careerRank='Подростковая подработка'}],['Сосредоточиться на учёбе · 10 энергии','Ум +5',s=>{s.energy=clamp(s.energy-10);s.mind=clamp(s.mind+5)}]]};if(state.age===18)eventNow={title:'Взрослая жизнь',text:'Открыты взрослые карьеры, самостоятельная работа и новые решения.',choices:[['Выбрать карьеру','Открыть список профессий',s=>{}],['Продолжить учёбу · 10 энергии','Ум +4',s=>{s.energy=clamp(s.energy-10);s.mind=clamp(s.mind+4)}]]};if(state.age>=100){endLife();break}}persist();renderGame()};
action=function(a){const costs={activityPlay:5,activityToy:15,activityAdult:8,activityDraw:8,activitySport:12,activityFriend:6,activityWork:15};if(a==='rest'){if(state.energy<5){toast('Нужно 5 энергии, чтобы спокойно отдохнуть.');return}state.energy-=5;state.mood=clamp(state.mood+1);state.health=clamp(state.health+1);state.fatigue=clamp(state.fatigue+2);state.resting=true;log('Отдохнул. Энергия восстановится при переходе следующего месяца.');persist();renderGame();toast('Отдых запланирован на следующий месяц');return}if(costs[a]){let cost=costs[a];if(state.energy<cost){toast(`Нужно ${cost} энергии. Сначала отдохни или перейди к следующему месяцу.`);return}state.energy-=cost;state.fatigue=clamp(state.fatigue+Math.ceil(cost/4));if(a==='activityPlay'){state.mood=clamp(state.mood+5);state.relations=clamp(state.relations+6);log('Поиграл вместе с близкими. Близость +6.')}if(a==='activityToy'||a==='activityAdult'){state.relations=clamp(state.relations+10);state.charisma=clamp((state.charisma||15)+1);state.mood=clamp(state.mood+2);log(a==='activityToy'?'Вместе искали любимую игрушку. Близость +10.':'Позвал взрослого и получил поддержку. Близость +10.')}if(a==='activityDraw'){state.mind=clamp(state.mind+2);state.mood=clamp(state.mood+3);state.career=state.age<14?'Художник':state.career;state.careerRank=state.age<14?'Детское увлечение':state.careerRank;state.album.unshift('Занимался рисованием.');log('Занимался рисованием. Интеллект +2.')}if(a==='activitySport'){state.fitness=clamp((state.fitness||20)+3);state.health=clamp(state.health+1);log('Потренировался. Фитнес +3.')}if(a==='activityFriend'){state.relations=clamp(state.relations+5);state.mood=clamp(state.mood+4);log('Провёл время с другом.')}if(a==='activityWork'){if(state.age<14){toast('Подработка доступна с 14 лет');return}state.money+=3500;log('Подработал и отложил 3 500 ₽.')}persist();renderGame();return}if(a==='school'&&state.age<6){toast('Школа начнётся в 6 лет. Пока можно играть, рисовать и общаться.');return}priorAction2(a)};
renderGame=function(){if(!state)return;state.charisma??=15;state.fitness??=20;state.appearance??=50;priorRenderGame2();const top=document.querySelector('.game-top');if(top){top.innerHTML=`<div class="metric money"><div class="metric-name"><span>${state.age<14?'Личные деньги':esc(state.name)}</span><span>${esc(state.symbol)}</span></div><div class="metric-value">${fmt(state.money)} ${esc(state.symbol)}</div><div class="muted" style="font-size:11px">${state.age<14?'Личный счёт персонажа':esc(state.city+', '+state.country)}</div></div>${metric('Энергия',state.energy)}${metric('Здоровье',state.health)}${metric('Счастье',state.mood)}<button class="stats-toggle" id="statsToggle">Показатели⌄</button>`;top.insertAdjacentHTML('afterend',`<div class="more-stats" id="moreStats" hidden>${metric('Интеллект',state.mind)}${metric('Харизма',state.charisma)}${metric('Фитнес',state.fitness)}${metric('Внешность',state.appearance)}</div>`);$('#statsToggle').onclick=()=>{let x=$('#moreStats');x.hidden=!x.hidden;$('#statsToggle').textContent=x.hidden?'Показатели⌄':'Показатели⌃'};}const familyCard=document.querySelector('.family-budget');if(view==='home'&&state.age<18&&!familyCard){const fc=document.querySelector('.content .forecast');if(fc)fc.insertAdjacentHTML('afterend',`<div class="list-row family-budget"><span>Семейный бюджет</span><b>${fmt(state.familyFunds||0)} ${esc(state.symbol)}</b></div>`)}const av=document.querySelector('.hero .avatar');if(av)av.innerHTML=`<span class="portrait ${state.age<6?'baby':state.age<14?'child':state.age<25?'teen':state.age<60?'adult':'elder'}"><i class="hair"></i><i class="face"></i><i class="body"></i></span>`;const c=$('#modalContent .forecast');if(c&&$('#modalContent .birthdoc')){c.innerHTML=`Ваша история начинается здесь: <b>${esc(state.city)}, ${esc(state.country)}</b>. Семья: ${esc(state.familyType||'Полная семья')}.`}}
if(state?.name)renderGame();else renderSetup();

