const renderRef=renderGame, actionRef=action;
renderGame=function(){renderRef();document.querySelector('.family-budget')?.remove();const f=document.querySelector('.content .forecast');if(f&&state.age<14&&!f.querySelector('.family-budget-inline'))f.insertAdjacentHTML('beforeend',`<small class="family-budget-inline">Семейный бюджет: ${fmt(state.familyFunds||0)} ${esc(state.symbol)}</small>`)};
action=function(a){if(a==='activityWork'&&state.age>=14&&state.age<18){if(state.energy<15){toast('Нужно 15 энергии, чтобы пойти на подработку.');return}state.energy-=15;state.fatigue=clamp(state.fatigue+4);state.money+=3500;state.career='Подработка';state.careerRank='Подростковая подработка';log('Подработал и отложил 3 500 ₽.');persist();renderGame();return}actionRef(a)};
if(state?.name)renderGame();else renderSetup();

function ensurePeople(){
 if(!state?.name)return;
 state.familyType??=['Полная семья','Мама и папа','Мама и бабушка'][Math.floor(Math.random()*3)];
 state.parents??='Родители заботятся о ребёнке';
 state.parentTraits??=['Терпеливые','Активные','Спокойные','Заботливые'][Math.floor(Math.random()*4)];
 state.people??=[];
 if(state.people.length)return;
 const women=['Анна','Мария','Елена','Ольга','Ирина','Наталья'],men=['Алексей','Сергей','Дмитрий','Павел','Михаил','Иван'];
 const pick=a=>a[Math.floor(Math.random()*a.length)],bond=clamp(38+(state.relations||0)/4);
 state.people.push({id:'mother',name:pick(women),role:'Мама',closeness:bond});
 if(state.familyType==='Мама и бабушка')state.people.push({id:'grandma',name:pick(women),role:'Бабушка',closeness:bond+3});
 else state.people.push({id:'father',name:pick(men),role:'Папа',closeness:bond});
}
function relationshipCards(){
 ensurePeople();
 return (state.people||[]).map(p=>'<article class="person-card"><div class="person-head"><div><b>'+esc(p.name)+'</b><small>'+esc(p.role)+'</small></div><span class="pill">Близость '+Math.round(p.closeness)+' / 100</span></div><div class="meter"><span style="width:'+clamp(p.closeness)+'%"></span></div><button class="btn small ghost" data-action="personTime_'+esc(p.id)+'">Провести время · 5 энергии</button></article>').join('')||'<p class="muted">Персонажи семьи появятся здесь.</p>';
}
const relBaseRender=renderGame, relBaseAction=action, relBaseChoose=chooseEvent;
relationsView=function(){ensurePeople();return '<div class="card"><span class="eyebrow">БЛИЗКИЕ</span><h2>Отношения с людьми</h2><p class="muted">У каждого близкого своя шкала. Совместное время и решения меняют отношения отдельно.</p>'+relationshipCards()+'<div class="list-row"><span>Общие отношения</span><span class="pill">'+Math.round(state.relations)+' / 100</span></div><div class="modal-actions"><button class="btn ghost" data-action="friend">Познакомиться с другом</button><button class="btn ghost" data-action="date">Пойти на свидание</button><button class="btn ghost" data-action="gift">Подарить подарок</button></div></div>'};
familyView=function(){return '<div class="card"><span class="eyebrow">БЛИЗКИЕ</span><h2>Семья и отношения</h2>'+relationshipCards()+'<div class="list-row"><span>Семейное положение</span><span class="pill">'+(state.married?'В браке':'Не в браке')+'</span></div><div class="list-row"><span>Дети</span><span class="pill">'+state.children+'</span></div><h3>Альбом памятных моментов</h3>'+state.album.map(a=>'<div class="log-entry">📷 '+esc(a)+'</div>').join('')+'<button class="btn small ghost" data-action="note">＋ Заметка в альбом</button></div>'};
renderGame=function(){ensurePeople();relBaseRender()};
action=function(a){
 if(a==='friend'){relBaseAction(a);ensurePeople();if(!state.people.some(p=>p.role==='Друг')){let names=state.gender==='Женский'?['София','Алиса','Полина','Даша']:['Петя','Артём','Максим','Даня'];let nm=names[Math.floor(Math.random()*names.length)];state.people.push({id:'friend'+Date.now(),name:nm,role:'Друг',closeness:35});log('Познакомился с другом: '+nm+'.');persist();renderGame()}return}
 if(a.startsWith('personTime_')){ensurePeople();let p=state.people.find(x=>x.id===a.slice(11));if(!p)return;if(state.energy<5){toast('Нужно 5 энергии. Отдохни или перейди к следующему месяцу.');return}state.energy-=5;state.fatigue=clamp(state.fatigue+2);p.closeness=clamp(p.closeness+6);state.relations=clamp(state.relations+2);state.mood=clamp(state.mood+3);log('Провёл время с '+p.name+'. Близость +6.');persist();renderGame();return}
 if(['activityPlay','activityToy','activityAdult'].includes(a)){relBaseAction(a);let p=state.people.find(x=>x.role==='Мама')||state.people[0];if(p){p.closeness=clamp(p.closeness+(a==='activityPlay'?6:10));persist();renderGame()}return}
 relBaseAction(a)
};
