action=function(a){if(a==='footballRandomTrial'){ensureFootball();let f=state.football;if(state.age<14){toast('Просмотры доступны с 14 лет');return}if(f.contract){toast('Дождись окончания текущего контракта');return}if(f.offers.length){toast('Сначала рассмотри предложение клуба');return}if(f.injuredMonths){toast('Сначала восстановись после травмы');return}if(state.energy<12){toast('Нужно 12 энергии для просмотра');return}state.energy-=12;state.fatigue=clamp(state.fatigue+3);let club=chooseRandomClubOffer(),req=club.min-(state.age<18?15:0),chance=Math.min(.9,.3+Math.max(0,f.skill-req)/90);if(Math.random()<chance){f.offers=[club.id];log('Случайный просмотр: '+club.name+' пригласил на контракт.');toast('Клуб прислал предложение: '+club.name)}else{f.form=clamp(f.form-4);log('Случайный просмотр в клубе '+club.name+': пока отказ.');toast('Клуб пока отказал. Тренируйся и попробуй позже')}persist();renderGame();return}if(a==='footballTrial_'||a.startsWith('footballTrial_')){toast('Список клубов скрыт: пройди случайный просмотр.');return}if(a==='footballMatch'){ensureFootball();let f=state.football,bg=f.goals,ba=f.assists,bm=f.matches,bs=f.season.matches;productActionBase(a);if(f.matches>bm){let scored=f.goals-bg,assist=scored>0&&Math.random()<.58?1:0;f.assists=ba+assist;f.season.matches=bs+1;f.season.goals=(f.season.goals||0)+scored;f.season.assists=(f.season.assists||0)+assist;persist();renderGame()}return}return productActionBase(a)};
const productTickBase=monthlyTick;
monthlyTick=function(){let prior=state?.football?.contract?{clubName:state.football.contract.clubName,monthsLeft:state.football.contract.monthsLeft}:null;productTickBase();if(prior&&state.career==='Футболист'&&!state.football?.contract&&state.age>=14){ensureFootball();let club=chooseRandomClubOffer();state.football.offers=[club.id];log('Контракт с '+prior.clubName+' завершён. Случайное предложение поступило от клуба '+club.name+'.');toast('Новый контракт: предложение от '+club.name);persist()}};
const productAnnualBase=annualTick;
annualTick=function(){productAnnualBase();if(state.career!=='Футболист')return;ensureFootball();let f=state.football,season=f.season||{matches:0,goals:0,assists:0},club=FOOTBALL_CLUBS.find(c=>c.name===f.contract?.clubName)||FOOTBALL_CLUBS.find(c=>c.name===f.club),rating=(f.skill+f.form+f.fitness)/3,contribution=season.goals+season.assists;function trophy(key,label){f.trophies[key]=(f.trophies[key]||0)+1;let msg='Завоевал трофей: '+label+'.';log(msg);state.album.unshift(msg)}function award(label){f.awards.push(state.year+' · '+label);if(f.awards.length>40)f.awards.shift();log('Футбольная награда: '+label+'.')}if(club&&f.contract&&season.matches>=8){let leagueChance=Math.max(.04,Math.min(.62,.08+(rating-45)/150+contribution/220));if(Math.random()<leagueChance)trophy('league','чемпионат '+(club.country==='ОАЭ'?'ОАЭ':club.country));if(Math.random()<leagueChance*.48)trophy('nationalCup','кубок '+(club.country==='ОАЭ'?'ОАЭ':club.country));if(club.country==='ОАЭ'){if(Math.random()<leagueChance*.3)trophy('afc','Азиатская Лига чемпионов')}else{if(rating>=78&&Math.random()<leagueChance*.32)trophy('ucl','Лига чемпионов УЕФА');else if(rating>=66&&Math.random()<leagueChance*.38)trophy('europa','Лига Европы УЕФА');else if(Math.random()<leagueChance*.3)trophy('conference','Лига конференций УЕФА')}}if(state.age>=18&&state.year%4===2&&rating>=65&&Math.random()<Math.min(.7,(rating+state.reputation)/180)){if(Math.random()<.14)trophy('worldCup','чемпионат мира');else log('Вызван в сборную на чемпионат мира.')}if(season.matches>=8&&contribution>=12)award('Лучший игрок сезона');if(season.matches>=10&&season.goals>=15)award('Золотая бутса');if(state.age<=21&&season.matches>=8&&rating>=65&&contribution>=8)award('Лучший молодой игрок');if(season.matches>=12&&rating>=82&&contribution>=25&&Math.random()<.25)award('Золотой мяч');f.season={matches:0,goals:0,assists:0};if(state.age>=6&&state.age<=14){state.schoolClass=state.age-5;state.educationPath='school';state.education='Школа · '+state.schoolClass+' класс'}else if(state.age===15&&!state.educationChoiceDone){state.schoolClass=9;eventNow={title:'После 9 класса',text:'Девять классов позади. Можно получить профессию в колледже или продолжить учиться в старших классах.',choices:[['Колледж · программирование','Профессия и практические занятия',s=>{s.educationPath='college';s.collegeSpecialty='Программирование';s.collegeYear=1;s.education='Колледж · 1 курс';s.educationChoiceDone=true}],['Колледж · медицина','Подготовка к медицинской профессии',s=>{s.educationPath='college';s.collegeSpecialty='Медицина';s.collegeYear=1;s.education='Колледж · 1 курс';s.educationChoiceDone=true}],['Колледж · спорт и тренерство','Спортивная специальность и практика',s=>{s.educationPath='college';s.collegeSpecialty='Спорт и тренерство';s.collegeYear=1;s.education='Колледж · 1 курс';s.educationChoiceDone=true}],['Продолжить в 10 классе','Закончить 10 и 11 класс',s=>{s.educationPath='school';s.schoolClass=10;s.education='Школа · 10 класс';s.educationChoiceDone=true}]]}}else if(state.educationPath==='college'&&state.age>=16&&state.age<=17){state.collegeYear=state.age-14;state.education='Колледж · '+state.collegeYear+' курс · '+state.collegeSpecialty}else if(state.educationPath==='college'&&state.age>=18){state.collegeYear=3;state.education='Колледж окончен · '+state.collegeSpecialty}else if(state.educationPath==='school'&&state.age>=15&&state.age<=16){state.schoolClass=state.age-5;state.education='Школа · '+state.schoolClass+' класс'}else if(state.educationPath==='school'&&state.age>=17){state.schoolClass=11;state.education='Школа окончена · 11 классов'}};
function educationLabel(){if(!state)return '';if(state.age<3)return 'Дома с семьёй';if(state.age<6)return 'Детский сад · '+['младшая','средняя','подготовительная'][Math.max(0,state.age-3)]+' группа';if(state.educationPath==='college')return state.age>=18?'Колледж окончен · '+(state.collegeSpecialty||'специальность'):'Колледж · '+(state.collegeYear||1)+' курс · '+(state.collegeSpecialty||'специальность');if(state.age>=17)return 'Школа окончена · 11 классов';let grade=state.schoolClass||Math.max(1,Math.min(11,state.age-5));return 'Школа · '+grade+' класс'}
