const eduActionBase=action;
action=function(a){if(a==='activityKindergarten'){if(state.age<3||state.age>=6){toast('Детский сад доступен с 3 до 5 лет');return}if(state.energy<8){toast('Нужно 8 энергии');return}state.energy-=8;state.fatigue=clamp(state.fatigue+2);state.mind=clamp(state.mind+1);state.relations=clamp(state.relations+2);state.mood=clamp(state.mood+3);log('Провёл день в детском саду: игры, занятия и новые знакомства.');persist();renderGame();return}if(a==='school'){if(state.age<6){toast('Школа начинается с 6 лет; до этого можно ходить в детский сад.');return}if(state.energy<10){toast('Нужно 10 энергии для занятий');return}state.energy-=10;state.fatigue=clamp(state.fatigue+3);state.mind=clamp(state.mind+2);if(state.educationPath==='college')state.schoolGrade=Math.min(5,(state.schoolGrade||3)+.1);log(state.educationPath==='college'?'Посетил занятия в колледже · '+(state.collegeSpecialty||'общее направление')+'.':'Посетил занятия · '+educationLabel()+'.');persist();renderGame();return}return eduActionBase(a)};
const eduAdvanceBase=advance;
