function footballYouthEvent(){return {title:'Переход в молодёжный футбол',text:'Ты уже играешь за клуб. Теперь можно сосредоточиться на футбольном развитии или совмещать тренировки с учёбой.',choices:[['Продолжить карьеру в клубе','Техника +3 · форма +3',s=>{ensureFootball();s.football.skill=clamp(s.football.skill+3);s.football.form=clamp(s.football.form+3);s.career='Футболист';s.careerRank='Молодёжный игрок · '+(s.football.club||s.football.contract?.clubName||'академия');s.footballYouthTransitionDone=true}],['Учёба и футбол','Ум +4 · техника +1',s=>{ensureFootball();s.mind=clamp(s.mind+4);s.football.skill=clamp(s.football.skill+1);s.career='Футболист';s.footballYouthTransitionDone=true}]]}}
