const completeFootballChooseBase=chooseEvent;
function playFootballFinal(index){let ev=eventNow,comp=ev.competition,styles=[{name:'Высокий прессинг',bonus:(state.football.fitness-50)/8},{name:'Контроль мяча',bonus:state.football.skill/12+state.mind/15},{name:'Быстрые контратаки',bonus:state.football.form/9},{name:'Поддержать команду',bonus:(state.charisma||15)/9+state.relations/18},{name:'Смелая атакующая схема',bonus:state.football.skill/10-(state.energy<20?12:0)}],style=styles[index]||styles[0],f=state.football;f.finalStats??={played:0,wins:0,losses:0};f.finalStats.played++;let rating=(f.skill*.42+f.form*.23+f.fitness*.2+state.mind*.08+(state.reputation||0)*.07),chance=Math.max(12,Math.min(92,49+(rating-60)*.55+style.bonus)),won=Math.random()*100<chance;f.competitionResults[comp.key]??={played:0,wins:0,losses:0};let cr=f.competitionResults[comp.key];cr.played++;f.matches++;let goals=won?1+Math.floor(Math.random()*3):Math.floor(Math.random()*2),assists=goals>0?Math.min(goals,Math.floor(Math.random()*2)):0;f.goals+=goals;f.assists+=assists;if(won){f.wins++;f.finalStats.wins++;cr.wins++;f.competitions[comp.key]=(f.competitions[comp.key]||0)+1;footballCompetitionNames[comp.key]=comp.name;state.reputation=clamp((state.reputation||0)+2);state.mood=clamp(state.mood+7);f.form=clamp(f.form+9)}else{f.losses++;f.finalStats.losses++;cr.losses++;f.form=clamp(f.form-6)}let line={number:f.matches,date:monthName()+' '+state.year,club:f.contract?.clubName||f.club||'Сборная',opponent:'соперник в финале',result:won?'Победа':'Поражение',goals,assists,competition:comp.name};f.matchLog.push(line);f.tournamentHistory.push({year:state.year,competition:comp.name,result:line.result,club:line.club,style:style.name});if(f.matchLog.length>3000)f.matchLog.shift();if(f.tournamentHistory.length>500)f.tournamentHistory.shift();log((won?'Выиграл финал: ':'Проиграл финал: ')+comp.name+'. Тактика: '+style.name+'.');eventNow=null;persist();renderGame();openModal(won?'ТРОФЕЙ ВЫИГРАН':'ФИНАЛЬНЫЙ МАТЧ','Финал · '+comp.name,'<div class="forecast"><b>'+(won?'Поздравляем! Вы выиграли «'+esc(comp.name)+'»!':'В этот раз трофей достался сопернику.')+'</b><br>Тактика: '+esc(style.name)+'. Результат сезона записан в статистику.</div><div class="modal-actions"><button class="btn primary" data-close>Продолжить</button></div>');}
chooseEvent=function(i){if(eventNow?.kind==='footballFinal'){playFootballFinal(i);return}if(eventNow?.kind==='footballAward'){let ev=eventNow,benefit=[()=>{state.relations=clamp(state.relations+5);state.mood=clamp(state.mood+2)},()=>{let p=state.people?.[0];if(p)p.closeness=clamp(p.closeness+6);state.relations=clamp(state.relations+3)},()=>{state.mood=clamp(state.mood+6);state.reputation=clamp((state.reputation||0)+1)},()=>{state.charisma=clamp((state.charisma||15)+3);state.reputation=clamp((state.reputation||0)+2)}][i]||(()=>{});benefit();log('Церемония: вручена награда «'+ev.award+'».');eventNow=null;persist();renderGame();openModal('НАГРАДА ВРУЧЕНА',ev.award,'<div class="forecast">Поздравляем! Ты получил награду «<b>'+esc(ev.award)+'</b>». Твоя речь и благодарность записаны в историю.</div><div class="modal-actions"><button class="btn primary" data-close>Продолжить</button></div>');return}let title=eventNow?.title;if(title==='Первые деньги'&&state.career==='Футболист')eventNow=footballYouthEvent();completeFootballChooseBase(i)};
const completeFootballAdvanceBase=advance;
advance=function(n){if(eventNow){renderGame();toast('Сначала выбери вариант события');return}for(let i=0;i<n&&!state.dead;i++){completeFootballAdvanceBase(1);if(!eventNow&&state.career==='Футболист'&&state.football?.eventQueue?.length)setNextFootballEvent();if(eventNow){renderGame();break}}};

// Keep competition labels and the statistics button available in older saves too.
const labelEnsureFootballBase=ensureFootball;
ensureFootball=function(){labelEnsureFootballBase();if(state?.career!=='Футболист')return;let f=state.football;f.competitionLabels??={};for(const r of f.tournamentHistory||[])if(r.key&&r.competition)f.competitionLabels[r.key]=r.competition};
const playFinalForLabelsBase=playFootballFinal;
playFootballFinal=function(i){let comp=eventNow?.competition;playFinalForLabelsBase(i);if(comp&&state?.football){state.football.competitionLabels??={};state.football.competitionLabels[comp.key]=comp.name;let r=state.football.tournamentHistory?.at(-1);if(r)r.key=comp.key;persist()}};
footballStatsHtml=function(){ensureFootball();let f=state.football;if(!f)return '<p>Статистика пока недоступна.</p>';let comps=Object.entries(f.competitions||{}).filter(([,n])=>n>0),matches=(f.matchLog||[]).slice().reverse(),awards=(f.awards||[]).slice().reverse(),aliases={league:'Чемпионат страны',nationalCup:'Кубок страны',ucl:'Лига чемпионов УЕФА',europa:'Лига Европы УЕФА',conference:'Лига конференций УЕФА',worldCup:'Чемпионат мира',afc:'Лига чемпионов АФК'};return '<div class="football-stats-modal"><div class="football-stat-summary"><div><small>МАТЧИ</small><b>'+f.matches+'</b></div><div><small>ПОБЕДЫ</small><b>'+f.wins+'</b></div><div><small>ПОРАЖЕНИЯ</small><b>'+f.losses+'</b></div><div><small>НИЧЬИ</small><b>'+f.draws+'</b></div><div><small>ГОЛЫ</small><b>'+f.goals+'</b></div><div><small>ГОЛЕВЫЕ</small><b>'+f.assists+'</b></div></div><h3>Выигранные трофеи</h3>'+(comps.length?'<div class="football-trophy-grid">'+comps.map(([k,n])=>'<div class="football-trophy"><span>'+esc(f.competitionLabels?.[k]||footballCompetitionNames[k]||aliases[k]||k)+'</span><b>'+n+'</b></div>').join('')+'</div>':'<p class="muted">Пока нет выигранных трофеев.</p>')+'<h3>Финалы</h3>'+(f.tournamentHistory?.length?f.tournamentHistory.slice().reverse().map(t=>'<div class="log-entry">'+esc(t.year)+' · '+esc(t.competition)+' · '+esc(t.result)+(t.style?' · тактика: '+esc(t.style):'')+'</div>').join(''):'<p class="muted">Финалы появятся после сыгранных сезонов.</p>')+'<h3>Личные награды</h3>'+(awards.length?'<div class="football-award-list">'+awards.map(a=>'<div class="log-entry">🏅 '+esc(a)+'</div>').join('')+'</div>':'<p class="muted">Награды появятся по итогам хороших сезонов.</p>')+'<details class="football-match-details"><summary>Все матчи · '+matches.length+'</summary>'+(matches.length?matches.map(m=>'<div class="log-entry"><b>'+esc(m.date)+' · '+esc(m.competition||'Матч')+'</b><br>'+esc(m.club||'Клуб')+' — '+esc(m.opponent||'соперник')+': '+esc(m.result)+' · голы '+m.goals+' · голевые '+m.assists+'</div>').join(''):(f.history||[]).slice().reverse().map(x=>'<div class="log-entry">'+esc(x)+'</div>').join('')||'<p class="muted">Матчей пока нет.</p>')+'</details></div>'};
const statButtonPanelBase=footballPanel;
footballPanel=function(){let html=statButtonPanelBase();if(html&&!html.includes('data-action="footballStats"'))html=html.replace('</h2>','</h2><button class="btn small ghost" data-action="footballStats">📊 Статистика</button>');return html};

const footballEducationBaseTick=annualTick;
annualTick=function(){footballEducationBaseTick();if(state.age>=6&&state.age<=14){state.schoolClass=state.age-5;state.educationPath='school';state.education='Школа · '+state.schoolClass+' класс'}else if(state.age===15&&!state.educationChoiceDone){state.schoolClass=9;eventNow={title:'После 9 класса',text:'Девять классов позади. Выбери колледж или продолжи учиться в старших классах.',choices:[['Колледж · программирование','Профессия и практика',s=>{s.educationPath='college';s.collegeSpecialty='Программирование';s.collegeYear=1;s.education='Колледж · 1 курс';s.educationChoiceDone=true}],['Колледж · медицина','Подготовка к медицинской профессии',s=>{s.educationPath='college';s.collegeSpecialty='Медицина';s.collegeYear=1;s.education='Колледж · 1 курс';s.educationChoiceDone=true}],['Колледж · спорт','Спортивная специальность и практика',s=>{s.educationPath='college';s.collegeSpecialty='Спорт';s.collegeYear=1;s.education='Колледж · 1 курс';s.educationChoiceDone=true}],['Остаться в школе','Перейти в 10 класс',s=>{s.educationPath='school';s.schoolClass=10;s.education='Школа · 10 класс';s.educationChoiceDone=true}]]}}else if(state.educationPath==='college'&&state.age>=16&&state.age<=17){state.collegeYear=state.age-14;state.education='Колледж · '+state.collegeYear+' курс · '+(state.collegeSpecialty||'специальность')}else if(state.educationPath==='college'&&state.age>=18){state.collegeYear=3;state.education='Колледж окончен · '+(state.collegeSpecialty||'специальность')}else if(state.educationPath==='school'&&state.age>=15&&state.age<=16){state.schoolClass=state.age-5;state.education='Школа · '+state.schoolClass+' класс'}else if(state.educationPath==='school'&&state.age>=17){state.schoolClass=11;state.education='Школа окончена · 11 классов'}};

