function ensurePossessions(){if(!state)return;state.ownedPhones??=[];state.ownedCars??=[];state.ownedHomes??=[];state.ownedClothes??=[];state.ownedHelicopters??=[];state.ownedYachts??=[];if(state.phone&&state.phone!=='Простой телефон'&&!state.ownedPhones.length){let p=possessionCatalog.find(x=>x.name===state.phone);if(p)state.ownedPhones.push(p.id)}if(state.car&&state.car!=='Нет машины'&&!state.ownedCars.length){let p=possessionCatalog.find(x=>x.name===state.car);if(p)state.ownedCars.push(p.id)}if(state.house&&state.house!=='Съёмная комната'&&!state.ownedHomes.length){let p=possessionCatalog.find(x=>x.name===state.house);if(p)state.ownedHomes.push(p.id)}if(state.clothes==='Тёплая зимняя одежда'&&!state.ownedClothes.length)state.ownedClothes.push('clothesWinter');for(const bucket of ['ownedPhones','ownedCars','ownedHomes','ownedClothes','ownedHelicopters','ownedYachts'])state[bucket]=[...new Set(state[bucket])];}
function possessionBucket(p){return p.kind==='phone'?'ownedPhones':p.kind==='car'?'ownedCars':p.kind==='house'?'ownedHomes':p.kind==='clothes'?'ownedClothes':p.kind==='helicopter'?'ownedHelicopters':'ownedYachts'}
function possessionKindLabel(kind){return kind==='phone'?'Телефон':kind==='car'?'Машина':kind==='house'?'Дом':kind==='clothes'?'Одежда':kind==='helicopter'?'Вертолёт':'Яхта'}
const productSvgBeforeTransport=productSvg;
productSvg=function(kind,variant){if(kind==='helicopter')return '<svg class="product-art" viewBox="0 0 320 150" role="img" aria-label="Иллюстрация вертолёта"><rect width="320" height="150" rx="12" fill="#dceaf0"/><circle cx="260" cy="32" r="18" fill="#f5d88b"/><path d="M0 122q70-25 150-8t170-3v39H0z" fill="#aabe9c"/><ellipse cx="167" cy="111" rx="70" ry="7" fill="#243b46" opacity=".2"/><path d="M88 82q12-26 46-26h54q20 0 32 17l25 5q8 2 8 10v9h-44q-10 14-28 14h-54q-22 0-35-15H78V88q0-5 10-6z" fill="#'+(['456f78','536887','b45b38'][variant%3])+'"/><path d="M127 61h52q14 0 22 15h-79z" fill="#dff1f0"/><path d="M157 56V38m-80 0h165M137 37h42" stroke="#243b46" stroke-width="4" stroke-linecap="round"/><path d="M211 91h47" stroke="#243b46" stroke-width="4"/><path d="M230 80l31 10-31 10" fill="#b45b38"/></svg>';if(kind==='yacht')return '<svg class="product-art" viewBox="0 0 320 150" role="img" aria-label="Иллюстрация яхты"><defs><linearGradient id="yg'+variant+'" x2="0" y2="1"><stop stop-color="#dcebf0"/><stop offset="1" stop-color="#a9c8d0"/></linearGradient></defs><rect width="320" height="150" rx="12" fill="url(#yg'+variant+')"/><circle cx="255" cy="30" r="18" fill="#f2d78c"/><path d="M0 98q45-9 90 0t90 0 140 0v52H0z" fill="#53889a"/><path d="M0 115q42-8 84 0t84 0 152 0" fill="none" stroke="#d9edf0" stroke-width="4"/><ellipse cx="165" cy="119" rx="100" ry="7" fill="#1c3541" opacity=".2"/><path d="M65 96h194l-29 30H91z" fill="#f7f3e8" stroke="#344d57" stroke-width="2"/><path d="M112 96V67h81v29" fill="#'+(['4c7380','626789','a75d44'][variant%3])+'"/><path d="M123 74h24v13h-24m35-13h24v13h-24" fill="#d8edf0"/><path d="M151 36v31h68z" fill="#fffaf0" stroke="#9b7656"/><path d="M147 36v31h-53z" fill="#e1d0ae" stroke="#9b7656"/><path d="M105 130h164" stroke="#fff" stroke-width="3"/></svg>';return productSvgBeforeTransport(kind,variant)};
const oldMoneyViewPossession=moneyView;
moneyView=function(){ensurePossessions();let categories=['Телефоны','Машины','Жильё','Одежда','Воздушный транспорт','Водный транспорт'],cards=possessionCatalog.map(p=>{let owned=state[possessionBucket(p)].includes(p.id);let art=p.kind==='clothes'?'<div class="product-art clothes-art clothes-'+p.icon+'">'+(p.icon===0?'👕':p.icon===1?'🧥':p.icon===2?'🧥':'🧥')+'</div>':productSvg(p.kind,p.icon);return '<article class="product-card" data-category="'+esc(p.cat)+'">'+art+'<div class="product-info"><span class="eyebrow">'+esc(p.cat)+' · '+esc(p.bonus)+'</span><h3>'+esc(p.name)+(p.id==='carOld'?' · плохое состояние':'')+'</h3><p>'+esc(p.desc)+'</p><div class="product-cost">'+(p.bill?'<small>Расходы: '+fmt(p.bill)+' '+esc(state.symbol)+' / месяц</small>':'<small>Постоянных расходов нет</small>')+'</div><div class="product-buy"><b>'+fmt(p.price)+' '+esc(state.symbol)+'</b><button class="btn small '+(owned?'ghost':'primary')+'" data-buy="'+esc(p.id)+'" '+(owned?'disabled':'')+'>'+(owned?'Уже куплено':'Купить')+'</button></div></div></article>'}).join('');let regular=possessionCatalog.filter(p=>state[possessionBucket(p)].includes(p.id)).reduce((s,p)=>s+p.bill,0);return '<div class="card"><span class="eyebrow">ФИНАНСЫ И ПОКУПКИ</span><h2>Магазин вещей и транспорта</h2><div class="forecast"><strong>Баланс: '+fmt(state.money)+' '+esc(state.symbol)+'</strong><span class="muted">Регулярные расходы на покупки: '+fmt(regular)+' '+esc(state.symbol)+' в месяц</span></div><div class="tabs"><button class="tab-btn active" data-tab="Все">Все покупки</button>'+categories.map(x=>'<button class="tab-btn" data-tab="'+esc(x)+'">'+esc(x)+'</button>').join('')+'</div><div class="product-grid">'+cards+'</div><div class="modal-actions"><button class="btn ghost" data-action="credit">＋ Кредит</button><button class="btn ghost" data-action="sell">Продать имущество</button><button class="btn ghost" data-action="invest">Вложить деньги</button></div><div class="notice">Покупки дают небольшие бонусы. Машины, жильё, связь, вертолёт и яхта требуют ежемесячных расходов.</div>'+'</div>'};
const buyBeforePossession=buy;
buy=function(type){ensurePossessions();let id=type==='clothes'?'clothesWinter':type,product=possessionCatalog.find(p=>p.id===id);if(!product)return buyBeforePossession(type);if(state.age<18){toast('Покупки доступны с 18 лет');return}let bucket=possessionBucket(product);if(state[bucket].includes(product.id)){toast('Эта вещь уже куплена');return}if(state.money<product.price){toast('Не хватает денег на покупку');return}state.money-=product.price;state[bucket].push(product.id);let label=product.name;if(product.kind==='phone')state.phone=label;if(product.kind==='car')state.car=label;if(product.kind==='house')state.house=label;if(product.kind==='clothes')state.clothes=label;state.appearance=clamp((state.appearance||50)+(product.kind==='clothes'?product.mood:product.kind==='car'?2:0));state.charisma=clamp((state.charisma||15)+(product.kind==='phone'?Math.max(1,Math.floor(product.mood/2)):product.kind==='clothes'&&product.id==='clothesBrand'?3:0));state.mood=clamp(state.mood+product.mood);state.reputation=clamp((state.reputation||0)+(product.kind==='car'&&product.id==='car5'?5:product.kind==='clothes'&&product.id==='clothesLuxury'?3:0));state.achievements.push('Покупка: '+label);log('Куплено: '+label+'. Настроение +'+product.mood+'. Ежемесячные расходы: '+fmt(product.bill)+' '+state.symbol+'.');persist();renderGame();toast(label+' куплен. Настроение улучшилось!')};
const upkeepTickBase=monthlyTick;
monthlyTick=function(){ensurePossessions();let boughtHouse=state.ownedHomes.length>0;upkeepTickBase();ensurePossessions();let bill=0,comfort=0;for(const p of possessionCatalog)if(state[possessionBucket(p)].includes(p.id)){bill+=p.bill;if(p.kind==='house')comfort=Math.max(comfort,Math.floor(p.mood/4));if(p.kind==='car'&&p.mood>=4)comfort=Math.max(comfort,1)}if(boughtHouse&&state.age>=18)state.money+=3500;if(bill){state.money-=bill;log('Ежемесячные расходы на содержание имущества и связь: '+fmt(bill)+' '+state.symbol+'.')}if(comfort)state.mood=clamp(state.mood+comfort);if(bill&&state.money<0){state.mood=clamp(state.mood-2);log('Из-за расходов на имущество пришлось экономить. Настроение −2.')}state.monthlyPossessionBill=bill};

// Relationship milestones: dating, engagement, marriage and raising children.
function ensureFamilyLife(){if(!state)return;state.children??=0;state.childRecords??=[];state.people??=[];state.people.forEach(p=>{if(p.role==='Девушка'||p.role==='Парень'){p.relationshipStatus??=(state.married&&state.partnerId===p.id?'В браке':'Знакомство');if(state.married&&!state.partnerId){state.partnerId=p.id;p.relationshipStatus='В браке'}}});if(state.married&&state.partnerId){let p=state.people.find(x=>x.id===state.partnerId);if(p)p.relationshipStatus='В браке'}}
const romanceCreateBase=createSocialPerson;
createSocialPerson=function(kind){let before=state?.people?.length||0;romanceCreateBase(kind);if(kind==='romance'&&state?.people?.length>before){let p=state.people[state.people.length-1];p.relationshipStatus='Знакомство';p.closeness=Math.max(p.closeness||0,35);persist();renderGame()}};
function romancePanel(){ensureFamilyLife();let person=state.people.find(p=>(p.role==='Девушка'||p.role==='Парень')&&p.relationshipStatus!=='Расстались');if(!person)return '<div class="card romance-card"><span class="eyebrow">РОМАНТИЧЕСКИЕ ОТНОШЕНИЯ</span><h3>Пока нет пары</h3><p class="muted">В разделе «Отношения» можно познакомиться с девушкой или парнем с 14 лет. Сначала общайтесь, затем ходите на свидания.</p>'+(state.age>=14?'<button class="btn primary" data-action="meetRomance">Познакомиться</button>':'<p class="muted">Знакомства станут доступны с 14 лет.</p>')+'</div>';let status=person.relationshipStatus||'Знакомство',action='';if(state.married&&state.partnerId===person.id){action='<button class="btn ghost" data-action="romanceDate_'+esc(person.id)+'">Провести время вместе · 8 энергии</button>'+(state.children<5?'<button class="btn primary" data-action="haveChild_'+esc(person.id)+'">Попробовать завести ребёнка</button>':'<p class="muted">В семье уже пятеро детей.</p>')}else if(status==='Помолвлены'){action='<button class="btn primary" data-action="wedding_'+esc(person.id)+'">Сыграть свадьбу · 30 000 '+esc(state.symbol)+'</button>'}else if(status==='Встречаются'){action='<button class="btn ghost" data-action="romanceDate_'+esc(person.id)+'">Сходить на свидание · 8 энергии</button>'+(state.age>=18&&person.closeness>=72?'<button class="btn primary" data-action="propose_'+esc(person.id)+'">Предложить пожениться</button>':'<p class="muted">Чтобы сделать предложение, нужно быть старше 18 лет и укрепить отношения до 72.</p>')}else{action='<button class="btn ghost" data-action="romanceDate_'+esc(person.id)+'">Позвать на свидание · 8 энергии</button>'+(person.closeness>=55?'<button class="btn primary" data-action="startDating_'+esc(person.id)+'">Предложить встречаться</button>':'<p class="muted">Проведите несколько свиданий, чтобы близость выросла до 55.</p>')}return '<div class="card romance-card"><span class="eyebrow">РОМАНТИЧЕСКИЕ ОТНОШЕНИЯ</span><h3>'+esc(person.name)+'</h3><div class="list-row"><span>Этап отношений</span><b>'+esc(status)+'</b></div><div class="list-row"><span>Близость</span><b>'+Math.round(person.closeness)+' / 100</b></div><div class="meter"><span style="width:'+clamp(person.closeness)+'%"></span></div><p class="muted">'+(person.hobby?'Увлекается '+esc(person.hobby)+'. ':'')+'Постепенно укрепляйте отношения: знакомство → свидания → пара → помолвка → свадьба.</p><div class="modal-actions">'+action+'</div>'+(state.married&&state.partnerId===person.id?'<div class="notice">Семья живёт в городе '+esc(state.city)+'. Расходы на детей будут учитываться каждый месяц.</div>':'')+'</div>'}
const familyRelationsViewBase=relationsView,familyTreeViewBase=familyView;
relationsView=function(){ensureFamilyLife();return familyRelationsViewBase()+romancePanel()};
familyView=function(){ensureFamilyLife();let kids=state.childRecords.map(c=>'<div class="list-row"><span>👶 '+esc(c.name)+' '+esc(c.surname||state.surname)+'</span><b>'+(c.ageYears||0)+' лет</b></div>').join(''),spouse=state.people.find(p=>p.id===state.partnerId);return familyTreeViewBase()+'<div class="card family-life-card"><span class="eyebrow">СЕМЬЯ</span><h2>Совместная жизнь</h2><div class="list-row"><span>Партнёр</span><b>'+(spouse?esc(spouse.name)+' · '+esc(spouse.relationshipStatus||'В браке'):'Пока нет')+'</b></div><div class="list-row"><span>Детей</span><b>'+state.children+'</b></div>'+(kids||'<p class="muted">Когда появятся дети, их имена и возраст отобразятся здесь.</p>')+(state.married?'<div class="notice">После свадьбы можно проводить время вместе и планировать детей.</div>':'<p class="muted">Чтобы создать семью, познакомься с партнёром и пройди этапы отношений.</p>')+'</div>'};
const romanceActionBase=action;
action=function(a){if(a==='meetRomance'){if(state.age<14){toast('Романтические знакомства доступны с 14 лет');return}ensureFamilyLife();if(state.people.some(p=>(p.role==='Девушка'||p.role==='Парень')&&p.relationshipStatus!=='Расстались')){toast('Сначала развивай уже начатые отношения');return}createSocialPerson('romance');return}if(a.startsWith('romanceDate_')){ensureFamilyLife();let p=state.people.find(x=>x.id===a.slice(12));if(!p)return;if(state.energy<8){toast('Нужно 8 энергии для свидания');return}state.energy-=8;state.fatigue=clamp(state.fatigue+3);p.closeness=clamp(p.closeness+12);state.relations=clamp(state.relations+3);state.mood=clamp(state.mood+6);log('Сходил на свидание с '+p.name+'. Близость +12.');state.album.unshift('Свидание с '+p.name);persist();renderGame();toast('Свидание прошло хорошо');return}if(a.startsWith('startDating_')){ensureFamilyLife();let p=state.people.find(x=>x.id===a.slice(12));if(!p||p.closeness<55){toast('Сначала укрепите отношения до 55');return}if(state.age<14){toast('Отношения доступны с 14 лет');return}p.relationshipStatus='Встречаются';state.relations=clamp(state.relations+4);log('Начал встречаться с '+p.name+'.');state.album.unshift('Начали встречаться с '+p.name);persist();renderGame();toast('Вы теперь пара!');return}if(a.startsWith('propose_')){ensureFamilyLife();let p=state.people.find(x=>x.id===a.slice(8));if(!p||state.age<18||p.relationshipStatus!=='Встречаются'||p.closeness<72){toast('Для предложения нужно быть совершеннолетним и иметь близость не ниже 72');return}let chance=Math.min(.96,.58+p.closeness/280+(state.reputation||0)/500);if(Math.random()<chance){p.relationshipStatus='Помолвлены';p.closeness=clamp(p.closeness+5);log(p.name+' принял(а) предложение. Вы помолвлены!');state.album.unshift('Помолвка с '+p.name);toast('Поздравляем с помолвкой!')}else{p.closeness=clamp(p.closeness-4);log(p.name+' попросил(а) пока не торопиться со свадьбой.');toast('Партнёр пока не готов. Проведите ещё время вместе')}persist();renderGame();return}if(a.startsWith('wedding_')){ensureFamilyLife();let p=state.people.find(x=>x.id===a.slice(8));if(!p||state.age<18||p.relationshipStatus!=='Помолвлены'){toast('Сначала нужно обручиться');return}if(state.money<30000){toast('На свадьбу нужно 30 000 '+state.symbol);return}state.money-=30000;state.married=true;state.partnerId=p.id;state.marriageYear=state.year;p.relationshipStatus='В браке';p.closeness=clamp(p.closeness+8);state.relations=clamp(state.relations+8);state.mood=clamp(state.mood+10);log('Сыграли свадьбу с '+p.name+'.');state.album.unshift('Свадьба · '+p.name);persist();renderGame();openModal('СЕМЬЯ СОЗДАНА','Свадьба','<div class="forecast">Поздравляем! Ты и <b>'+esc(p.name)+'</b> теперь семья. Можно строить совместную жизнь и позже решить, хотите ли вы детей.</div><div class="modal-actions"><button class="btn primary" data-close>Продолжить</button></div>');return}if(a.startsWith('haveChild_')){ensureFamilyLife();let p=state.people.find(x=>x.id===a.slice(10));if(!p||!state.married||state.partnerId!==p.id){toast('Сначала нужно создать семью');return}if(state.children>=5){toast('В семье уже пятеро детей');return}if(state.energy<10||state.money<15000){toast(state.energy<10?'Нужно 10 энергии':'Нужно 15 000 '+state.symbol);return}state.energy-=10;state.money-=15000;state.fatigue=clamp(state.fatigue+4);if(Math.random()<.72){let girls=['София','Алиса','Полина','Милана','Ева','Варвара'],boys=['Артём','Максим','Даниил','Илья','Матвей','Лев'],female=Math.random()<.5,first=(female?girls:boys)[Math.floor(Math.random()*(female?girls.length:boys.length))],child={name:first,surname:state.surname,gender:female?'Женский':'Мужской',ageYears:0,ageMonths:0,birthYear:state.year,birthMonth:state.month};state.childRecords.push(child);state.children=state.childRecords.length;state.mood=clamp(state.mood+12);p.closeness=clamp(p.closeness+6);log('В семье родился ребёнок: '+child.name+' '+child.surname+'.');state.album.unshift('Рождение ребёнка · '+child.name);persist();renderGame();openModal('НОВЫЙ ЧЛЕН СЕМЬИ','Рождение ребёнка','<div class="forecast">В вашей семье родился ребёнок — <b>'+esc(child.name)+' '+esc(child.surname)+'</b>. Семейная история продолжается!</div><div class="modal-actions"><button class="btn primary" data-close>Продолжить</button></div>')}else{log('Решили пока не торопиться с пополнением семьи.');persist();renderGame();toast('Пополнение семьи пока не получилось. Можно попробовать позже')}return}if(a==='family'){toast('Чтобы создать семью, сначала познакомься и пройди этапы отношений');view='relations';renderGame();return}return romanceActionBase(a)};
const childrenTickBase=monthlyTick;
monthlyTick=function(){childrenTickBase();ensureFamilyLife();if(state.married&&state.children){let cost=state.children*4500;state.money-=cost;state.monthlyFamilyBill=cost;if(state.money<0)state.mood=clamp(state.mood-1);for(const c of state.childRecords){c.ageMonths=(c.ageMonths||0)+1;if(c.ageMonths>=12){c.ageMonths-=12;c.ageYears=(c.ageYears||0)+1;if(c.ageYears===1||c.ageYears===7||c.ageYears===18){let text=c.ageYears===1?'сделал первые шаги':c.ageYears===7?'пошёл в школу':'стал совершеннолетним';log(c.name+' '+text+'.');state.album.unshift(c.name+' · '+c.ageYears+' лет')}}}}};

// Top-level controls for starting a fresh saved life and changing game settings.
function nextLifeSlot(){let saved=slots(),i=1,name;do{name='Жизнь '+i;i++}while(saved[name]);return name}
function beginNewLife(){if(state?.name){persist();window.lifeNewSlotPending=nextLifeSlot()}else window.lifeNewSlotPending=nextLifeSlot();if(dlg.open)dlg.close();state=null;localStorage.removeItem('lifeActive');renderSetup();updateTopControls();toast('Предыдущее прохождение сохранено. Создай нового персонажа.')}
function applyLifeTheme(dark){document.body.classList.toggle('dark',!!dark);localStorage.setItem('lifeTheme',dark?'dark':'light');if(state?.name){state.dark=!!dark;persist()}}
function openGameSettings(){let active=!!state?.name, dark=document.body.classList.contains('dark'), music=!!state?.sound, autosave=active?state.autosave!==false:true;openModal('НАСТРОЙКИ','Настройки игры','<div class="settings-list"><div class="settings-row"><div><b>Оформление</b><small>Выбери светлую или тёмную тему</small></div><button class="btn ghost" id="settingsTheme">'+(dark?'Тёмная тема':'Светлая тема')+'</button></div><div class="settings-row"><div><b>Музыка</b><small>'+(active?'Спокойная фоновая мелодия':'Станет доступна после начала жизни')+'</small></div><button class="btn ghost" id="settingsMusic" '+(active?'':'disabled')+'>'+(music?'Выключить':'Включить')+'</button></div><div class="settings-row"><div><b>Автосохранение</b><small>Сохранение в конце каждого игрового года</small></div><button class="btn ghost" id="settingsAutosave" '+(active?'':'disabled')+'>'+(autosave?'Включено':'Выключено')+'</button></div><div class="settings-row"><div><b>Слоты жизней</b><small>Старые прохождения можно загрузить из меню сохранений</small></div><button class="btn ghost" id="settingsSlots">Открыть сохранения</button></div></div>');document.querySelector('#settingsTheme').onclick=()=>{let v=!document.body.classList.contains('dark');applyLifeTheme(v);document.querySelector('#settingsTheme').textContent=v?'Тёмная тема':'Светлая тема'};document.querySelector('#settingsMusic').onclick=()=>{if(!state?.name)return;if(lifeMusicTimer)lifeMusicOff();else lifeMusicOn().catch(()=>toast('Не получилось включить музыку'));document.querySelector('#settingsMusic').textContent=state.sound?'Выключить':'Включить'};document.querySelector('#settingsAutosave').onclick=()=>{if(!state?.name)return;state.autosave=state.autosave===false;persist();document.querySelector('#settingsAutosave').textContent=state.autosave?'Включено':'Выключено';toast(state.autosave?'Автосохранение включено':'Автосохранение выключено')};document.querySelector('#settingsSlots').onclick=()=>{dlg.close();openSlots()}}
function updateTopControls(){let b=document.querySelector('#newGameBtn');if(b)b.hidden=!state?.name}
const settingsGameStartBase=startGame;
startGame=function(){let slot=window.lifeNewSlotPending||null;settingsGameStartBase();if(state?.name&&slot){state.slot=slot;window.lifeNewSlotPending=null;persist()}};
const settingsRenderGameBase=renderGame,settingsRenderSetupBase=renderSetup;
renderGame=function(){settingsRenderGameBase();updateTopControls()};
renderSetup=function(){settingsRenderSetupBase();updateTopControls()};
const newGameButton=document.querySelector('#newGameBtn');if(newGameButton)newGameButton.onclick=beginNewLife;
const settingsButton=document.querySelector('#settingsBtn');if(settingsButton)settingsButton.onclick=openGameSettings;
const activeStartButton=document.querySelector('#startGame');if(activeStartButton)activeStartButton.onclick=startGame;
const settingsThemeButton=document.querySelector('#themeBtn');if(settingsThemeButton)settingsThemeButton.onclick=()=>applyLifeTheme(!document.body.classList.contains('dark'));
if(localStorage.getItem('lifeTheme')==='dark')document.body.classList.add('dark');updateTopControls();

