const roleCareerViewBase=careerView;
function businessDashboard(){if(state.career!=='Бизнесмен'||state.age<18)return '';state.businesses??=[];const catalog=[['cafe','Кофейня',80000,18000],['restaurant','Ресторан',350000,62000],['shop','Магазин одежды',120000,26000],['studio','IT-студия',200000,42000],['taxi','Служба такси',160000,35000],['hotel','Отель',800000,125000],['academy','Футбольная академия',420000,70000]];return '<div class="card business-hub"><span class="eyebrow">СВОЁ ДЕЛО</span><h2>Бизнесы и проекты</h2><p class="muted">Открой дело, нанимай сотрудников и вкладывай прибыль в развитие.</p>'+state.businesses.map((b,i)=>'<div class="business-row"><div><b>'+esc(b.name)+'</b><small>Уровень '+b.level+' · сотрудников '+b.staff+' · доход около '+fmt(b.income)+' '+esc(state.symbol)+'/мес.</small></div><button class="btn small ghost" data-action="businessUpgrade_'+i+'">Развивать · '+fmt(b.cost)+' '+esc(state.symbol)+'</button></div>').join('')+(state.businesses.length?'<div class="notice">Ежемесячное обслуживание всех проектов: '+fmt(state.businesses.reduce((a,b)=>a+b.upkeep,0))+' '+esc(state.symbol)+'.</div>':'<p class="muted">Пока бизнесов нет.</p>')+'<h3>Открыть новое дело</h3><div class="business-grid">'+catalog.map(([id,name,cost,income])=>'<button class="career-option" data-action="businessStart_'+id+'"><strong>'+name+'</strong><small>Вложение '+fmt(cost)+' '+esc(state.symbol)+' · возможный доход '+fmt(income)+' / месяц</small></button>').join('')+'</div></div>'}
careerView=function(){let html=roleCareerViewBase();if(state.career==='Тренер')html+='<div class="card coach-hub"><span class="eyebrow">ТРЕНЕРСКАЯ КАРЬЕРА</span><h2>'+esc(state.coachRank||'Начинающий тренер')+'</h2><p>После завершения игровой карьеры можно тренировать команду, развивать молодых игроков и бороться за трофеи.</p><div class="list-row"><span>Команда</span><b>'+esc(state.coachClub||'Молодёжная команда')+'</b></div><div class="list-row"><span>Репутация тренера</span><b>'+Math.round(state.coachReputation||0)+'/100</b></div><div class="modal-actions"><button class="btn ghost" data-action="coachTraining">Провести тренировку</button><button class="btn ghost" data-action="coachTactics">Подготовить тактику</button><button class="btn primary" data-action="coachOffer">Запросить просмотр клуба</button></div></div>';return html+businessDashboard()};
const roleFamilyViewBase=familyView;
familyView=function(){let html=roleFamilyViewBase();return html+'<div class="card family-activities"><span class="eyebrow">СЕМЕЙНЫЕ ВОСПОМИНАНИЯ</span><h3>Провести время всей семьёй</h3><p class="muted">Общие занятия укрепляют отношения и пополняют семейный альбом.</p><div class="modal-actions"><button class="btn ghost" data-action="familyDinner">🍲 Семейный ужин · 2 000 '+esc(state.symbol)+'</button><button class="btn ghost" data-action="familyTrip">🎡 Выходной вместе · 5 000 '+esc(state.symbol)+' · 5 энергии</button><button class="btn ghost" data-action="familyHelp">📚 Помочь ребёнку с учёбой · 3 энергии</button></div>'+(state.familyStories?.length?'<h3>Истории семьи</h3>'+state.familyStories.slice(-8).reverse().map(x=>'<div class="log-entry">♡ '+esc(x)+'</div>').join(''):'')+'</div>'};
const roleActionBase=action;
action=function(a){if(a.startsWith('businessStart_')){let id=a.slice(14),catalog={cafe:['Кофейня',80000,18000],restaurant:['Ресторан',350000,62000],shop:['Магазин одежды',120000,26000],studio:['IT-студия',200000,42000],taxi:['Служба такси',160000,35000],hotel:['Отель',800000,125000],academy:['Футбольная академия',420000,70000]},p=catalog[id];if(!p)return;state.businesses??=[];if(state.businesses.length>=4){toast('Можно управлять максимум четырьмя бизнесами');return}if(state.money<p[1]){toast('Не хватает денег на открытие');return}state.money-=p[1];state.businesses.push({name:p[0],level:1,staff:2,income:p[2],upkeep:Math.round(p[2]*.22),cost:Math.round(p[1]*.55)});state.reputation=clamp((state.reputation||0)+2);log('Открыл бизнес: '+p[0]+'.');persist();renderGame();toast('Бизнес открыт!');return}if(a.startsWith('businessUpgrade_')){let b=state.businesses?.[Number(a.slice(16))];if(!b)return;if(state.money<b.cost){toast('Не хватает денег для развития');return}state.money-=b.cost;b.level++;b.staff+=2;b.income=Math.round(b.income*1.55);b.upkeep=Math.round(b.upkeep*1.35);b.cost=Math.round(b.cost*1.65);state.reputation=clamp((state.reputation||0)+1);log('Развил бизнес «'+b.name+'» до '+b.level+' уровня.');persist();renderGame();return}if(a==='retireFootball'){ensureFootball();if(state.age<35){toast('Завершить карьеру можно после 35 лет');return}state.football.retired=true;state.football.contract=null;state.career='Тренер';state.careerRank='Начинающий тренер';state.coachRank='Начинающий тренер';state.coachClub=state.football.club||'Молодёжная команда';state.coachReputation=clamp(Math.round((state.football.skill+state.football.form)/3));state.jobLevel=0;state.album.unshift('Завершение карьеры игрока · переход в тренеры');log('Завершил карьеру футболиста и стал тренером.');persist();renderGame();toast('Новая глава: тренерская карьера!');return}if(a==='coachTraining'||a==='coachTactics'||a==='coachOffer'){if(state.career!=='Тренер')return;if(a==='coachTraining'){state.coachReputation=clamp((state.coachReputation||0)+3);state.mood=clamp(state.mood+2);log('Провёл тренировку команды. Репутация тренера +3.')}if(a==='coachTactics'){state.coachReputation=clamp((state.coachReputation||0)+2);state.mind=clamp(state.mind+1);log('Подготовил новую тактику команды.')}if(a==='coachOffer'){let names=['Молодёжная команда','Клуб второго дивизиона','Клуб высшей лиги'];if((state.coachReputation||0)<15){toast('Нужно набрать больше тренерской репутации');return}state.coachClub=names[Math.min(2,Math.floor((state.coachReputation||0)/35))];state.coachRank=state.coachReputation>65?'Главный тренер':'Тренер клуба';state.careerRank=state.coachRank;state.coachReputation=clamp((state.coachReputation||0)+3);log('Получил тренерскую работу: '+state.coachClub+'.')}persist();renderGame();return}if(a==='familyDinner'||a==='familyTrip'||a==='familyHelp'){state.familyStories??=[];let cost=a==='familyDinner'?2000:a==='familyTrip'?5000:0,energy=a==='familyTrip'?5:a==='familyHelp'?3:0;if(state.money<cost||state.energy<energy){toast(state.money<cost?'Не хватает денег':'Не хватает энергии');return}state.money-=cost;state.energy-=energy;state.fatigue=clamp((state.fatigue||0)+energy);let note=a==='familyDinner'?'Собрались на семейный ужин и поговорили.':a==='familyTrip'?'Провели выходной всей семьёй.':'Помог ребёнку с учёбой и домашними заданиями.';state.familyStories.push(monthName()+' '+state.year+': '+note);state.familyStories=state.familyStories.slice(-40);state.mood=clamp(state.mood+5);state.relations=clamp(state.relations+4);for(let p of state.people||[])if(p.role==='Девушка'||p.role==='Парень'||p.role==='Мама'||p.role==='Папа')p.closeness=clamp((p.closeness||0)+4);state.album.unshift(note);persist();renderGame();return}return roleActionBase(a)};
const roleFootballPanelBase=footballPanel;
footballPanel=function(){let html=roleFootballPanelBase();if(!html)return html;let f=state.football;if(f.positionName)html+='<div class="notice football-position-note">Игровая позиция: <b>'+esc(f.positionName)+'</b></div>';if(state.age>=35&&!f.retired)html+='<div class="card"><h3>Завершение игровой карьеры</h3><p class="muted">Можно продолжить играть или перейти в тренеры.</p><button class="btn primary" data-action="retireFootball">Завершить карьеру и стать тренером</button></div>';return html};
