 let body=`<div class="season-award-report"><div class="notice"><b>${esc(r.club)}</b> · место в чемпионате: <b>${r.rank}</b> · ${esc(r.qualification)}</div><div class="season-report-grid"><div>Матчи <b>${r.matches}</b></div><div>Победы <b>${r.wins}</b></div><div>Ничьи <b>${r.draws}</b></div><div>Поражения <b>${r.losses}</b></div><div>Голы <b>${r.goals}</b></div><div>Голевые <b>${r.assists}</b></div><div>Жёлтые карточки <b>${r.yellow}</b></div><div>Красные карточки <b>${r.red}</b></div>${r.position==='GK'?`<div>Сухие матчи <b>${r.cleanSheets}</b></div>`:''}</div><h3>Церемония награждения · октябрь</h3>${r.awards.length?r.awards.map(a=>`<div class="notice">🏆 ${esc(a)}</div>`).join(''):'<p class="muted">В этом сезоне личных наград нет. Новый сезон — новый шанс!</p>'}<details><summary>Турнирная таблица</summary>${leagueTableHtml(r.table)}</details><p class="muted">Решение церемонии: ${esc(choice)}.</p><div class="modal-actions"><button class="btn primary" data-close>Продолжить</button></div></div>`;
 openModal('СЕЗОН ЗАВЕРШЁН','Награды и статистика · '+r.year,body);return
