const WORLD_BOARDS={overall:{name:'world_overall',label:'Общий рейтинг'},money:{name:'world_money',label:'Капитал'},football:{name:'world_football',label:'Футбольная карьера'},awards:{name:'world_awards',label:'Кубки и награды'}};
let worldBoardTab='overall',worldBoardRows={},worldBoardLoading=false,worldSyncTimer=null,worldSyncBusy=false,worldLastRead=0;
function normalizeNameForModeration(value){return String(value||'').normalize('NFKD').toLowerCase().replace(/[̀-ͯ]/g,'').replace(/ё/g,'е').replace(/[0о]/g,'о').replace(/[3]/g,'з').replace(/[4]/g,'ч').replace(/[5]/g,'с').replace(/[6]/g,'б').replace(/[1!]/g,'и').replace(/[xх]/g,'х').replace(/[yу]/g,'у').replace(/[pр]/g,'р').replace(/[aа]/g,'а').replace(/[eе]/g,'е').replace(/[cс]/g,'с').replace(/[oо]/g,'о').replace(/[kк]/g,'к').replace(/[mм]/g,'м').replace(/[tт]/g,'т').replace(/[bв]/g,'в').replace(/[hн]/g,'н').replace(/(.)\1+/g,'$1').replace(/[^a-zа-я]/g,'')}
function containsForbiddenName(value){let raw=String(value||'').normalize('NFKC').toLowerCase(),norm=normalizeNameForModeration(raw),ascii=raw.replace(/[^a-z0-9]/g,'').replace(/[0]/g,'o').replace(/[1!]/g,'i').replace(/[3]/g,'e').replace(/[4]/g,'a').replace(/[5$]/g,'s').replace(/[7]/g,'t').replace(/[8]/g,'b').replace(/(.)\1+/g,'$1');let ru=['хуй','хуя','хуе','хуи','пизд','бля','бляд','ебан','ебл','ебу','еба','ёб','заеб','наеб','уеб','выеб','проеб','доеб','мудак','мудил','гандон','залуп','манда','пидор','пидар','педик','сука','сучк'];let en=['fuck','shit','bitch','cunt','asshole','motherfucker','nigger','nigga','faggot','whore','rape','nazi','terrorist'];let translit=ascii.replace(/kh?uy|hui/g,'хуй').replace(/pizd/g,'пизд').replace(/blya/g,'бля').replace(/blyad/g,'бляд').replace(/yeb|ebat/g,'еб');let mixed=raw.replace(/[с]/g,'c').replace(/[ф]/g,'f').replace(/[и]/g,'i').replace(/[к]/g,'k').replace(/[а]/g,'a').replace(/[у]/g,'u').replace(/[х]/g,'x').replace(/[е]/g,'e').replace(/[б]/g,'b').replace(/[^a-z]/g,'');return ru.some(x=>norm.includes(x)||translit.includes(x))||en.some(x=>ascii.includes(x)||mixed.includes(x))||['гитлер','сваст','террор'].some(x=>norm.includes(x))}
function bindNameModeration(){for(let id of ['name','surname']){let input=document.getElementById(id);if(!input)continue;let label=input.closest('label');if(!label)continue;let hint=label.querySelector('.name-moderation-hint');if(!hint){hint=document.createElement('small');hint.className='name-moderation-hint';label.append(hint)}let update=()=>{let bad=containsForbiddenName(input.value);input.setAttribute('aria-invalid',bad?'true':'false');hint.textContent=bad?'Это слово нельзя использовать в имени. Попробуй другое.':'';hint.hidden=!bad};input.addEventListener('input',update);update()}}
