const moderatedRenderSetupBase=renderSetup;
renderSetup=function(){moderatedRenderSetupBase();bindNameModeration();let button=document.getElementById('startGame');if(button)button.onclick=startGame};
function worldRankingValues(s){let f=s.football||{},comps=Object.values(f.competitions||{}).reduce((a,n)=>a+(Number(n)||0),0),awards=(f.awards||[]).length,goals=f.goals||0,assists=f.assists||0,wins=f.wins||0,matches=f.matches||0,wealth=Math.max(0,Number(s.money)||0),moneyRaw=Math.floor(wealth);if(s.currency&&s.currency!=='RUB'&&Number(s.exchangeRate)>0)wealth*=Number(s.exchangeRate);let footballScore=goals*100+assists*75+wins*12+matches*2+(f.cleanSheets||0)*15,awardScore=comps*1000+awards*250,overall=Math.round(Math.log10(wealth+1)*10000+Math.min(9999,footballScore+awardScore));return{overall:Math.max(0,overall),money:Math.max(0,Math.floor(wealth)),football:Math.max(0,footballScore),awards:Math.max(0,awardScore),wealth:Math.floor(wealth),moneyRaw,currency:s.symbol||'₽',country:s.country||'',goals,assists,wins,matches,comps,awardsCount:awards,age:s.age||0,name:String(s.name||'Игрок').slice(0,24),surname:String(s.surname||'').slice(0,28),career:String(s.career||'').slice(0,32),club:String(f.contract?.clubName||f.club||'').slice(0,48)}}
function allLocalLives(){let all=Object.values(slots()||{});if(state?.name)all.push(state);let byName=new Map();for(let s of all){if(!s?.name||containsForbiddenName(s.name)||containsForbiddenName(s.surname||''))continue;let key=(s.name+' '+(s.surname||'')).toLowerCase(),row=worldRankingValues(s),old=byName.get(key);if(!old||row.overall>old.values.overall)byName.set(key,{name:s.name,surname:s.surname||'',values:row})}return [...byName.values()]}
function bestLocalValues(){let lives=allLocalLives();if(!lives.length&&state?.name)lives=[{name:state.name,surname:state.surname||'',values:worldRankingValues(state)}];return Object.fromEntries(Object.keys(WORLD_BOARDS).map(k=>[k,lives.sort((a,b)=>b.values[k]-a.values[k])[0]?.values||worldRankingValues(state||{})]))}
function worldRowsHtml(){let rows=worldBoardRows[worldBoardTab],key=worldBoardTab;if(worldBoardLoading)return '<div class="notice">Загружаю мировой рейтинг…</div>';if(!rows)return '<div class="notice">Нажми «Обновить рейтинг», чтобы посмотреть таблицу.</div>';if(rows.error)return '<div class="notice">'+esc(rows.error)+'</div>';if(!rows.length)return '<div class="notice">Пока нет результатов. Стань первым игроком в этой таблице!</div>';return '<div class="world-leader-list">'+rows.map((e,i)=>{let extra={};try{extra=JSON.parse(e.extraData||'{}')}catch{}let display=extra.character||[extra.name,extra.surname].filter(Boolean).join(' ')||e.player?.publicName||'Игрок',rank=e.rank||i+1,caption=key==='money'?(extra.moneyLabel||fmt(e.score)+' ₽'):key==='football'?'⚽ '+(extra.goals||0)+' голов · '+(extra.assists||0)+' голевых · '+(extra.wins||0)+' побед':key==='awards'?'🏆 '+(extra.cups||0)+' трофеев · '+(extra.awards||0)+' наград':'Капитал '+(extra.moneyLabel||'—')+' · ⚽ '+(extra.goals||0)+' · 🏆 '+(extra.cups||0);return '<div class="world-rank-row"><strong class="world-rank-place">'+rank+'</strong><div class="world-rank-person"><b>'+esc(display)+'</b><small>'+esc(caption)+(extra.country?' · '+esc(extra.country):'')+'</small></div><b class="world-rank-score">'+fmt(e.score)+'</b></div>'}).join('')+'</div>'}
function worldRankingView(){let tabs=Object.entries(WORLD_BOARDS).map(([id,b])=>'<button class="tab-btn '+(id===worldBoardTab?'active':'')+'" data-world-tab="'+id+'">'+esc(b.label)+'</button>').join(''),authorized=localStorage.getItem('lifeWorldRankingOptIn')==='yes';return '<div class="card world-ranking-card"><span class="eyebrow">ИГРОКИ ЯНДЕКС ИГР</span><h2>Мировой рейтинг</h2><p class="muted">Соревнуйся по капиталу, футбольной статистике, трофеям и общему результату. В ZIP-версии можно посмотреть только прохождения, сохранённые на этом устройстве.</p><div class="tabs world-board-tabs">'+tabs+'</div><div class="world-ranking-actions"><button class="btn ghost" id="worldRefresh">↻ Обновить рейтинг</button>'+(authorized?'<span class="pill good">Участие включено</span>':'<button class="btn primary" id="worldJoin">Войти и участвовать в мировом топе</button>')+'</div><div id="worldBoardContent">'+worldRowsHtml()+'</div>'+(authorized?'<p class="muted world-privacy-note">Имя персонажа и игровые показатели публично отправляются в таблицы Яндекс Игр.</p>':'<p class="muted world-privacy-note">Участие добровольное. Нажатие кнопки откроет вход Яндекс ID и включит публичную отправку игрового имени и показателей.</p>')+'</div><div class="card"><h3>Мои сохранённые прохождения</h3><p class="muted">Локальный список виден только на этом устройстве.</p>'+localLivesTableHtml()+'</div><div class="notice">Перед публикацией создай в Консоли разработчика Яндекс Игр числовые таблицы с названиями: <code>world_overall</code>, <code>world_money</code>, <code>world_football</code>, <code>world_awards</code>. Настрой сортировку по убыванию.</div>'}
function localLivesTableHtml(){let lives=allLocalLives().sort((a,b)=>b.values[worldBoardTab]-a.values[worldBoardTab]);if(!lives.length)return '<p class="muted">Пока нет сохранённых жизней.</p>';return lives.slice(0,10).map((x,i)=>'<div class="world-rank-row"><strong class="world-rank-place">'+(i+1)+'</strong><div class="world-rank-person"><b>'+esc(x.name+' '+x.surname)+'</b><small>'+esc(x.values.career||'Жизнь')+' · '+x.values.age+' лет</small></div><b class="world-rank-score">'+fmt(x.values[worldBoardTab])+'</b></div>').join('')}
async function refreshWorldLeaderboard(){if(!yandexGamesSdk&&window.YaGames)await initYandexGamesSdk();if(!yandexGamesSdk?.leaderboards){worldBoardRows[worldBoardTab]={error:'Мировой топ доступен после публикации на Яндекс Играх. Сейчас можно посмотреть только локальный список сохранений.'};worldBoardLoading=false;renderGame();return}if(Date.now()-worldLastRead<15000&&worldBoardRows[worldBoardTab]){toast('Подожди немного перед следующим обновлением');return}worldLastRead=Date.now();worldBoardLoading=true;renderGame();let board=WORLD_BOARDS[worldBoardTab];try{if(yandexGamesSdk.isAvailableMethod&&!await yandexGamesSdk.isAvailableMethod('leaderboards.getEntries'))throw new Error('Таблица пока недоступна. Проверь настройки лидербордов в Консоли разработчика.');let result=await yandexGamesSdk.leaderboards.getEntries(board.name,{quantityTop:20,includeUser:true,quantityAround:3});worldBoardRows[worldBoardTab]=result.entries||[]}catch(e){worldBoardRows[worldBoardTab]={error:String(e?.message||'Не удалось получить мировой рейтинг. После публикации проверь, что таблица '+board.name+' создана в Консоли разработчика.')}}finally{worldBoardLoading=false;if(view==='leaderboard')renderGame()}}
function rankingExtraData(v){return JSON.stringify({character:[v.name,v.surname].filter(Boolean).join(' ').slice(0,52),name:v.name,surname:v.surname,age:v.age,country:v.country,currency:v.currency,money:v.wealth,moneyLabel:fmt(v.moneyRaw)+' '+v.currency,goals:v.goals,assists:v.assists,wins:v.wins,matches:v.matches,cups:v.comps,awards:v.awardsCount,career:v.career,club:v.club})}
let worldSyncAgain=false;
async function syncWorldScores(){if(worldSyncBusy){worldSyncAgain=true;return}if(localStorage.getItem('lifeWorldRankingOptIn')!=='yes'||!yandexGamesSdk?.leaderboards||allLocalLives().length===0)return;let best=bestLocalValues();worldSyncBusy=true;try{let player=await yandexGamesSdk.getPlayer();if(!player?.isAuthorized?.())return;let sent={};try{sent=JSON.parse(localStorage.getItem('lifeWorldLastSent')||'{}')}catch{}for(const [key,board] of Object.entries(WORLD_BOARDS)){let score=best[key]?.[key]??0;if(score<=0||sent[board.name]===score)continue;if(yandexGamesSdk.isAvailableMethod&&!await yandexGamesSdk.isAvailableMethod('leaderboards.setScore'))continue;await yandexGamesSdk.leaderboards.setScore(board.name,score,rankingExtraData(best[key]));sent[board.name]=score;localStorage.setItem('lifeWorldLastSent',JSON.stringify(sent));await new Promise(resolve=>setTimeout(resolve,1100))}}catch(e){console.warn('World ranking sync failed',e)}finally{worldSyncBusy=false;if(worldSyncAgain){worldSyncAgain=false;scheduleWorldSync()}}}
function scheduleWorldSync(){if(localStorage.getItem('lifeWorldRankingOptIn')!=='yes')return;clearTimeout(worldSyncTimer);worldSyncTimer=setTimeout(syncWorldScores,3000)}
async function joinWorldRanking(){if(!yandexGamesSdk&&window.YaGames)await initYandexGamesSdk();if(!yandexGamesSdk){toast('Мировой топ работает после публикации игры на Яндекс Играх');return}try{let player=await yandexGamesSdk.getPlayer();if(!player?.isAuthorized?.()){openModal('УЧАСТИЕ В МИРОВОМ ТОПЕ','Публичный рейтинг','<p class="forecast">Если войти через Яндекс ID, имя персонажа и игровые показатели будут видны другим игрокам в мировых таблицах: капитал, голы, трофеи и общий результат. Участие добровольное.</p><div class="modal-actions"><button class="btn primary" id="worldAuthConfirm">Войти и отправить результаты</button><button class="btn ghost" data-close>Не сейчас</button></div>');document.getElementById('worldAuthConfirm').onclick=async()=>{dlg.close();try{await yandexGamesSdk.auth.openAuthDialog();player=await yandexGamesSdk.getPlayer();if(player?.isAuthorized?.()){localStorage.setItem('lifeWorldRankingOptIn','yes');await syncWorldScores();toast('Ты участвуешь в мировом рейтинге');renderGame();refreshWorldLeaderboard()}else toast('Вход не выполнен — прохождение остаётся личным')}catch(e){toast('Не удалось войти через Яндекс ID')}};return}localStorage.setItem('lifeWorldRankingOptIn','yes');await syncWorldScores();toast('Ты участвуешь в мировом рейтинге');renderGame();refreshWorldLeaderboard()}catch(e){toast('Рейтинг Яндекс Игр пока недоступен')}}
const worldRenderBase=renderGame;
renderGame=function(){worldRenderBase();if(!state?.name)return;let worldButton=document.querySelector('.sidebar [data-view="leaderboard"]');if(!worldButton){let worldAnchor=document.querySelector('.sidebar [data-view="world"]');if(worldAnchor){worldAnchor.insertAdjacentHTML('afterend','<button class="nav-btn" data-view="leaderboard"><span>🏆</span>Мировой рейтинг</button>');worldButton=document.querySelector('.sidebar [data-view="leaderboard"]');worldButton.onclick=()=>{view='leaderboard';worldBoardTab='overall';renderGame();refreshWorldLeaderboard()}}}if(view!=='leaderboard')return;let content=document.querySelector('.content');if(!content)return;content.innerHTML=worldRankingView();content.querySelectorAll('[data-world-tab]').forEach(b=>b.onclick=()=>{worldBoardTab=b.dataset.worldTab;renderGame();refreshWorldLeaderboard()});document.getElementById('worldRefresh')?.addEventListener('click',refreshWorldLeaderboard);document.getElementById('worldJoin')?.addEventListener('click',joinWorldRanking)};
const worldPersistBase=persist;
persist=function(){worldPersistBase();scheduleWorldSync()};
const nameSetupForWorldBase=renderSetup;
renderSetup=function(){nameSetupForWorldBase();bindNameModeration();let button=document.getElementById('startGame');if(button)button.onclick=startGame};
bindNameModeration();let initialStartButton=document.getElementById('startGame');if(initialStartButton)initialStartButton.onclick=startGame;if(state?.name)renderGame();





